-- ----------------------------
DROP TABLE IF EXISTS `flow_change_record`;
CREATE TABLE `flow_change_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `related_order_id` bigint NOT NULL COMMENT '关联单号ID',
  `order_type` int NOT NULL COMMENT '订单类型（枚举值：采购单、销售单、退款单、调账单等）',
  `amount_type` int NOT NULL COMMENT '金额类型（可用, 冻结, 已用, 总额）',
  `initial_amount` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '变更前金额（变更发生时的原始额度）',
  `final_amount` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '变更后金额（变更完成后的最终额度）',
  `change_amount` decimal(20, 6) NOT NULL DEFAULT 0.000000 COMMENT '变动金额（= final_amount - initial_amount，正数增加/负数减少）',
  `trader_id` bigint NOT NULL COMMENT '贸易商ID',
  `created_time` datetime NOT NULL COMMENT '创建时间',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人',
  `updated_time` datetime NOT NULL COMMENT '修改时间',
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新人',
  `delete_status` tinyint NOT NULL DEFAULT 0 COMMENT '删除状态',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '流水变更记录表（记录贸易商额度的每一次变更明细，支持追溯审计）' ROW_FORMAT = Dynamic;

