-- ----------------------------
DROP TABLE IF EXISTS `jf_anchor_product_stock_report`;
CREATE TABLE `jf_anchor_product_stock_report`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `batch_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '采集批次号',
  `goods_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品编号',
  `goods_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `application_scope` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '应用范围',
  `promotion_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '主推类型',
  `color_count` int NOT NULL DEFAULT 0 COMMENT '颜色个数',
  `yesterday_sales` int NOT NULL DEFAULT 0 COMMENT '上日销售',
  `month_sales` int NOT NULL DEFAULT 0 COMMENT '月销售',
  `spot_fabric_stock` int NOT NULL DEFAULT 0 COMMENT '现货色布（库存分类∈{1,2,3}）',
  `custom_fabric_stock` int NOT NULL DEFAULT 0 COMMENT '客订色布（库存分类=4）',
  `fabric_stock_subtotal` int NOT NULL DEFAULT 0 COMMENT '色布小计',
  `spot_running_stock` int NOT NULL DEFAULT 0 COMMENT '现货运转库存（库存分类∈{1,2,3}）',
  `custom_running_stock` int NOT NULL DEFAULT 0 COMMENT '客订运转库存（库存分类=4）',
  `running_stock_subtotal` int NOT NULL DEFAULT 0 COMMENT '运转小计',
  `fabric_total` int NOT NULL DEFAULT 0 COMMENT '色布合计',
  `fabric_upper_limit` int NOT NULL DEFAULT 0 COMMENT '色布上限',
  `over_upper_limit` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否超上限（1=是，0=否）',
  `dye_grey_huigrey` int NOT NULL DEFAULT 0 COMMENT '染厂坯布-花灰',
  `dye_grey_lightwhite` int NOT NULL DEFAULT 0 COMMENT '染厂坯布-浅白',
  `dye_grey_middeep` int NOT NULL DEFAULT 0 COMMENT '染厂坯布-中深',
  `dye_grey_black` int NOT NULL DEFAULT 0 COMMENT '染厂坯布-黑色',
  `dye_grey_abnormal` int NOT NULL DEFAULT 0 COMMENT '染厂坯布-异常色',
  `dye_grey_subtotal` int NOT NULL DEFAULT 0 COMMENT '染厂坯布小计',
  `weav_running_huigrey` int NOT NULL DEFAULT 0 COMMENT '织厂运转-花灰',
  `weav_running_lightwhite` int NOT NULL DEFAULT 0 COMMENT '织厂运转-浅白',
  `weav_running_middeep` int NOT NULL DEFAULT 0 COMMENT '织厂运转-中深',
  `weav_running_black` int NOT NULL DEFAULT 0 COMMENT '织厂运转-黑色',
  `weav_running_abnormal` int NOT NULL DEFAULT 0 COMMENT '织厂运转-异常色',
  `weav_running_subtotal` int NOT NULL DEFAULT 0 COMMENT '织厂运转小计',
  `grey_total` int NOT NULL DEFAULT 0 COMMENT '坯布合计',
  `grey_upper_limit` int NOT NULL DEFAULT 0 COMMENT '坯布上限',
  `stock_total` int NOT NULL DEFAULT 0 COMMENT '总库存合计',
  `stock_upper_limit` int NOT NULL DEFAULT 0 COMMENT '库存上限',
  `daily_output_huigrey` int NOT NULL DEFAULT 0 COMMENT '坯布日产-花灰',
  `daily_output_lightwhite` int NOT NULL DEFAULT 0 COMMENT '坯布日产-浅白',
  `daily_output_middeep` int NOT NULL DEFAULT 0 COMMENT '坯布日产-中深',
  `daily_output_black` int NOT NULL DEFAULT 0 COMMENT '坯布日产-黑色',
  `daily_output_subtotal` int NOT NULL DEFAULT 0 COMMENT '坯布日产小计',
  `planned_huigrey` int NOT NULL DEFAULT 0 COMMENT '已落计划未完成-花灰',
  `planned_lightwhite` int NOT NULL DEFAULT 0 COMMENT '已落计划未完成-浅白',
  `planned_middeep` int NOT NULL DEFAULT 0 COMMENT '已落计划未完成-中深',
  `planned_black` int NOT NULL DEFAULT 0 COMMENT '已落计划未完成-黑色',
  `planned_subtotal` int NOT NULL DEFAULT 0 COMMENT '已落计划未完成小计',
  `unplanned_huigrey` int NOT NULL DEFAULT 0 COMMENT '未落计划-花灰',
  `unplanned_lightwhite` int NOT NULL DEFAULT 0 COMMENT '未落计划-浅白',
  `unplanned_middeep` int NOT NULL DEFAULT 0 COMMENT '未落计划-中深',
  `unplanned_black` int NOT NULL DEFAULT 0 COMMENT '未落计划-黑色',
  `unplanned_subtotal` int NOT NULL DEFAULT 0 COMMENT '未落计划小计',
  `grand_total` int NOT NULL DEFAULT 0 COMMENT '总计',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'admin' COMMENT '创建者',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'admin' COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除状态',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_batch_no`(`batch_no` ASC) USING BTREE,
  INDEX `idx_spu_code`(`goods_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2982 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '主播产品库存播报表' ROW_FORMAT = DYNAMIC;

