-- ----------------------------
-- Table structure for jf_collection_account
-- ----------------------------
DROP TABLE IF EXISTS `jf_collection_account`;
CREATE TABLE `jf_collection_account`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账户编号',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收款账户名称',
  `icon` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图标',
  `trader_id` bigint NULL DEFAULT NULL COMMENT '贸易商id',
  `trader_short_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属贸易商简称 ',
  `pay_form_id` int NOT NULL COMMENT '支付方式（1：对公；2：动态码）',
  `settlement_traders` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设定贸易商',
  `open_account_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '开户银行全称【收款银行】',
  `open_account_branch` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开户行号',
  `open_account_registrant` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开户户名（jf_collection_bill列表的收款单位）【核算组织】',
  `open_account` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '开户账号【收款账号】',
  `open_account_address` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '开户地址',
  `bank_business_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '银行商编',
  `device_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备号',
  `is_company_account` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否公司账户 (0:否, 1:是)',
  `interest_rate` decimal(6, 2) NULL DEFAULT NULL COMMENT '利率 (%)',
  `currency_id` bigint NOT NULL COMMENT '交易币种ID',
  `accounting_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会计科目编码 (如: 1023)',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态 (0:禁用, 1:启用)',
  `sort_order` int NOT NULL DEFAULT 50 COMMENT '排序值',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  `detail_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开户详细地址',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pay_method`(`pay_form_id` ASC) USING BTREE,
  INDEX `idx_currency`(`currency_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5019 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '收款账户信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_collection_bill
-- ----------------------------
DROP TABLE IF EXISTS `jf_collection_bill`;
CREATE TABLE `jf_collection_bill`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收款单号',
  `collection_date` date NOT NULL COMMENT '收款日期',
  `bill_type` int NOT NULL DEFAULT 1 COMMENT '单据类型 (1:应收收款单，2：定金收款单，3：其它收款单)',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
  `customer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户编号',
  `customer_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户名称（往来单位）',
  `company` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '公司（单位全称）',
  `contacts_id` bigint NULL DEFAULT NULL COMMENT '联系人',
  `consignee` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收货人',
  `contact_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `trader_short_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '贸易商简称',
  `business_group` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务组别',
  `business_manager` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务经理',
  `store_sales` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '门店销售',
  `collection_notice_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款通知单号',
  `pay_method` int NULL DEFAULT NULL COMMENT '付款方式(1：对公转账；2：动态码付款)',
  `receipt_account_id` bigint NULL DEFAULT NULL COMMENT '收款账户ID',
  `collection_amount` decimal(18, 2) NOT NULL COMMENT '收款金额',
  `write_off_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '核销金额',
  `review_write_off_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '待核销金额',
  `currency_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '币种代码',
  `currency_rate` decimal(10, 6) NULL DEFAULT NULL COMMENT '币种汇率',
  `settlement_org` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '核算组织',
  `income_child_bill_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '进账子单号',
  `summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '摘要说明',
  `audit_status` int NOT NULL DEFAULT 1 COMMENT '状态 (1:待审核, 2:审核通过, 3:审核不通过)',
  `audit_opinion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核意见',
  `review` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `review_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `receivable_claim_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '应收认领单号（是否应收认领单生成）',
  `reservation_stock_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客订备货编码',
  `deposit` decimal(18, 2) NULL DEFAULT NULL COMMENT '订金金额',
  `receipt_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '已收订金金额',
  `no_receipt_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '未收订金金额',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  `remitter` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '汇款人',
  `customer_trader_short_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户贸易商简称',
  `version` int NULL DEFAULT 0 COMMENT '版本号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_customer`(`customer_id` ASC) USING BTREE,
  INDEX `idx_collection_notice`(`collection_notice_code` ASC) USING BTREE,
  INDEX `idx_pay_method`(`pay_method` ASC) USING BTREE,
  INDEX `idx_receipt_account`(`receipt_account_id` ASC) USING BTREE,
  INDEX `idx_income_bill`(`income_child_bill_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 476 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '收款单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_collection_notice
-- ----------------------------
DROP TABLE IF EXISTS `jf_collection_notice`;
CREATE TABLE `jf_collection_notice`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收款单号',
  `type` int NULL DEFAULT 0 COMMENT '单据类型:0=应收, 1=客订订金，2=预付款',
  `customer_id` bigint NOT NULL COMMENT '客户id',
  `customer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户编号',
  `customer_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户名称',
  `contacts_id` bigint NULL DEFAULT NULL COMMENT '联系人id',
  `consignee` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收货人',
  `contact_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '联系电话',
  `trader_short_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '贸易商简称',
  `business_group` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务组别',
  `business_manager` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务经理',
  `store_sales` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '门店销售',
  `payment_method` int NOT NULL COMMENT '支付方式：1=对公转账，2=动态码付款',
  `payment_status` int NOT NULL DEFAULT 1 COMMENT '支付状态：1=待支付；2=部分付款;3=已结清，4=已关闭',
  `settlement_org` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '核算组织',
  `collection_account_id` bigint NOT NULL COMMENT '收款账户ID',
  `open_account_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款账户',
  `open_account` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款账号',
  `collection_amount` decimal(14, 2) NULL DEFAULT NULL COMMENT '收款金额',
  `currency_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '币种代码',
  `currency_rate` decimal(10, 6) NULL DEFAULT NULL COMMENT '币种汇率',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注说明',
  `generation_mode` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生成方式',
  `close_flag` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否可关闭(1=可关闭，0=不可关闭(账单生成))',
  `is_tax_included` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否含税：1=是，0=否',
  `invoice_type` int NOT NULL DEFAULT 0 COMMENT '开票类型：0=不开票，1=普票，2=专票',
  `tax_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '税率',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除',
  `bill_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单据所属员',
  `bill_position` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单据所属岗位',
  `bill_department` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单据所属部门',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_customer`(`customer_id` ASC) USING BTREE,
  INDEX `idx_contacts`(`contacts_id` ASC) USING BTREE,
  INDEX `idx_payment_method`(`payment_method` ASC) USING BTREE,
  INDEX `idx_collection_account`(`collection_account_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2103345218772119554 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '收款通知单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_collection_notice_fee_item
-- ----------------------------
DROP TABLE IF EXISTS `jf_collection_notice_fee_item`;
CREATE TABLE `jf_collection_notice_fee_item`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `collection_notice_id` bigint NOT NULL COMMENT '收款通知单ID',
  `fee_item_id` bigint NOT NULL COMMENT '费项池ID',
  `fee_item_type` int NULL DEFAULT NULL COMMENT '费项类型（1=费项，2=税费）',
  `due_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '应收金额(快照(费项金额-费项已核销金额))',
  `generated_link_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '已生成链接金额',
  `current_write_off_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '当前核销金额(认领单核销时更新)',
  `unreceived_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '未收金额(应收-当前核销)认领单核销时更新',
  `received_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '已收金额(快照费项已核销金额)',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_collection_notice`(`collection_notice_id` ASC) USING BTREE,
  INDEX `idx_fee_item`(`fee_item_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2103345218902142979 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '收款通知单费用项目' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_collection_notice_link
-- ----------------------------
DROP TABLE IF EXISTS `jf_collection_notice_link`;
CREATE TABLE `jf_collection_notice_link`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
