  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '修改人',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态',
  `settlement_unit_id` bigint NULL DEFAULT NULL COMMENT '结算单位（签约公司主体）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 24 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '申请额度记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_contract_information
-- ----------------------------
DROP TABLE IF EXISTS `jf_contract_information`;
CREATE TABLE `jf_contract_information`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `oa_process_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'OA流程编号',
  `trader_abbreviation` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '贸易商简称',
  `customer_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '客户编号',
  `customer_abbreviation` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '客户简称',
  `company_full_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '公司全称',
  `business_manager` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '业务经理',
  `store_sales` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '门店销售',
  `apply_customer_level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请客户等级',
  `level_discount_unit_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '等级优惠单价（元）',
  `order_discount_method` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '下单优惠方式',
  `contract_start_time` date NOT NULL COMMENT '合同开始时间',
  `contract_end_time` date NOT NULL COMMENT '合同结束时间',
  `applicant` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请人',
  `apply_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '申请时间',
  `apply_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请原因',
  `customer_id` bigint NOT NULL COMMENT '客户id（关联客户表）',
  `status` tinyint NOT NULL COMMENT '合同状态 1-待生效；2-生效中；3-已过期；4-已取消；',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '创建人',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '修改人',
  `updated_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除状态',
  `oa_status` tinyint NULL DEFAULT NULL COMMENT 'oa状态',
  `strategy_or_sales` tinyint NOT NULL COMMENT '战略协议或销售协议 1-战略协议；2-销售协议',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_oa_process_no`(`oa_process_no` ASC) USING BTREE COMMENT 'OA流程编号唯一约束',
  INDEX `idx_customer_id`(`customer_id` ASC) USING BTREE COMMENT '客户id索引，关联客户查询',
  INDEX `idx_contract_time`(`contract_start_time` ASC, `contract_end_time` ASC) USING BTREE COMMENT '合同时间范围索引',
  INDEX `idx_apply_customer_level`(`apply_customer_level` ASC) USING BTREE COMMENT '客户等级索引，按等级筛选合同'
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '合同信息表' ROW_FORMAT = Dynamic;

