-- ----------------------------
-- Table structure for jf_contract_quota_customer
-- ----------------------------
DROP TABLE IF EXISTS `jf_contract_quota_customer`;
CREATE TABLE `jf_contract_quota_customer`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `customer_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户编号',
  `customer_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户名称',
  `trader` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '所属贸易商',
  `is_insured` tinyint(1) NULL DEFAULT NULL COMMENT '是否购买保险',
  `insurance_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '保险担保额度',
  `customer_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '客户等级',
  `apply_limit` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '申请额度',
  `credit_policy` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '信贷政策',
  `record_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '备案编码',
  `record_time` datetime NULL DEFAULT NULL COMMENT '备案时间(不等于创建时间)',
  `created_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态',
  `customer_id` bigint NULL DEFAULT NULL COMMENT '客户id',
  `oa_process_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'OA流程编号',
  `status` int NOT NULL COMMENT '状态1-审核中；2-审核通过；3-审核不通过；4-生效中；5-已过期；6-草稿',
  `temp_limit` decimal(18, 2) NULL DEFAULT NULL COMMENT '申请临时额度',
  `total_quota` decimal(10, 2) NULL DEFAULT NULL COMMENT '总额度(基本+临时+分配)',
  `available_quota` decimal(10, 2) NULL DEFAULT NULL COMMENT '可用额度（总额度-自己或他人用的）',
  `frozen_quota` decimal(10, 2) NULL DEFAULT NULL COMMENT '冻结额度（下单才冻结）',
  `used_quota` decimal(10, 2) NULL DEFAULT NULL COMMENT '已用额度（自己或他人用的总和）',
  `expire_quota` decimal(10, 2) NULL DEFAULT NULL COMMENT '即将到期额度',
  `expiration_date` date NULL DEFAULT NULL COMMENT '到期时间',
  `pay_form` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '支付形式',
  `sales_agreement_id` bigint NULL DEFAULT NULL COMMENT '销售协议id（获取开始结束时间）',
  `payment_periods` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款期数',
  `discount_credit_start_date` date NULL DEFAULT NULL COMMENT '优惠政策有效期开始日期',
  `discount_credit_end_date` date NULL DEFAULT NULL COMMENT '优惠政策有效期结束日期（到期需要修改客户表的客户等级为E）',
  `quota_start_date` date NULL DEFAULT NULL COMMENT '额度有效期开始日期（额度有效期优先取这个字段，没有再通过销售协议id取有效期）',
  `quota_end_date` date NULL DEFAULT NULL COMMENT '额度有效期结束日期（额度有效期优先取这个字段，没有再通过销售协议id取有效期）',
  `version_no` int NULL DEFAULT 1 COMMENT '版本号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 231 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '客户额度表（1、客户当前的额度优惠有效期到期了修改客户等级为E级\r\n2、总：100  基：90  临：10   冻：80   已：10  可：10\r\n2.1、上调额度：总：200  基：190  临：10   冻：80   已：10  可：110\r\n2.2、上调额度：总：70    基：60  临：10   冻：80   已：10  可：-20）' ROW_FORMAT = Dynamic;

