  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '记录主键ID',
  `customer_id` bigint NOT NULL COMMENT '客户id',
  `oa_process` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '关联oa流程编号',
  `trader_abbreviation` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '贸易商简称',
  `customer_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '客户编码',
  `customer_abbreviation` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '客户简称',
  `company` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '公司全称',
  `business_management` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '业务经理',
  `store_sales` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '门店销售',
  `apply_quota` decimal(10, 2) NULL DEFAULT NULL COMMENT '申请额度',
  `applicant` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请人',
  `apply_time` datetime NOT NULL COMMENT '申请时间',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请原因',
  `agreement_end_valid_date` date NOT NULL COMMENT '协议有效期（结束）',
  `agreement_start_valid_date` date NOT NULL COMMENT '协议有效期（开始）',
  `status` int NOT NULL COMMENT '状态1-审核通过；',
  `created_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '修改人',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态（删除在客户详情表示为已过期）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 211 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '销售协议表(每个客户当前只有一条生效，已删除的数据在客户详情页展示，新增客户额度时新增该表数据，到期自动修改客户支付形式为现金支付)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_contract_strategic_agreement
-- ----------------------------
DROP TABLE IF EXISTS `jf_contract_strategic_agreement`;
CREATE TABLE `jf_contract_strategic_agreement`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '记录主键ID',
  `record_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '备案编号',
  `oa_process` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '关联oa流程编号',
  `customer_id` bigint NOT NULL COMMENT '客户id',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标题',
  `agreement_status` int NOT NULL COMMENT '协议状态 1-协议已终止;2-延期中;3-即将到期;4-生效中;5-待生效;6-到期未达标;7-到期已达标;',
  `contract_tonnage` decimal(10, 2) NOT NULL COMMENT '合约采购吨数',
  `purchased_tonnage` decimal(10, 2) NOT NULL COMMENT '已采购吨数(已实际为主，弃用)',
  `completion_rate` decimal(5, 2) NOT NULL COMMENT '已达成比例（百分比）',
  `discount_method` int NOT NULL DEFAULT 2 COMMENT '优惠方式(1-先优惠；2-后优惠)',
  `belong_center` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '所属中心',
  `belong_department` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '所属部门',
  `company_id` bigint NULL DEFAULT NULL COMMENT '所属公司id',
  `belong_company` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '所属公司',
  `customer_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户名称',
  `customer_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户编码',
  `customer_short_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户简称',
  `current_customer_level` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户当前等级',
  `current_discount_price` decimal(10, 2) NOT NULL COMMENT '当前优惠单价(已实际为主，弃用)',
  `apply_discount_price` decimal(10, 2) NOT NULL COMMENT '申请优惠单价(已实际为主，弃用)',
  `pre_discount_amount` decimal(10, 2) NOT NULL COMMENT '前期优惠金额(已实际为主，弃用)',
  `post_discount_amount` decimal(10, 2) NOT NULL COMMENT '后期优惠金额(已实际为主，弃用)',
  `agreement_start_valid_date` date NOT NULL COMMENT '协议有效期（开始）',
  `agreement_end_valid_date` date NOT NULL COMMENT '协议有效期（结束）',
  `applicant` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请人',
  `apply_time` datetime NOT NULL COMMENT '申请时间',
  `created_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改人',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态',
  `current_customer_level_id` bigint NULL DEFAULT NULL COMMENT '客户当前等级id',
  `apply_level_id` bigint NULL DEFAULT NULL COMMENT '客户申请等级id',
  `is_rebate_settlement` tinyint(1) NULL DEFAULT 0 COMMENT '是否已返利',
  `apply_customer_level` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请客户等级',
  `first_party` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '甲方',
  `request_id` int NOT NULL DEFAULT 0 COMMENT 'oa流程的requestid',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '战略协议表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_contract_temp_quota_application_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_contract_temp_quota_application_record`;
CREATE TABLE `jf_contract_temp_quota_application_record`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '记录主键ID',
  `oa_flow_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'OA流程编号',
  `record_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备案编号',
  `status` int NOT NULL COMMENT '状态1-审核中；2-审核通过；3-审核不通过；4-生效中；5-已过期',
