  `created_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '修改人',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 71 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '临时额度申请记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_contract_termination
-- ----------------------------
DROP TABLE IF EXISTS `jf_contract_termination`;
CREATE TABLE `jf_contract_termination`  (
  `id` bigint NULL DEFAULT NULL COMMENT '主键',
  `created_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `updated_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '修改人',
  `strategic_agreement_id` bigint NULL DEFAULT NULL COMMENT 'jf_contract_strategic_agreement主键id',
  `agreement_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '战略协议编码',
  `original_end_date` date NOT NULL COMMENT '原结束日期',
  `termination_date` date NOT NULL COMMENT '申请终止日期',
