) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '战略协议终止申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_control_account_period
-- ----------------------------
DROP TABLE IF EXISTS `jf_control_account_period`;
