  `pay_form_id` bigint NOT NULL COMMENT '支付形式(1-现金支付；2-额度支付)',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '账期',
  `pay_day_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'oa同步，付款期数',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 (0:禁用, 1:启用)',
  `sort` int NULL DEFAULT 50 COMMENT '排序值',
