  `delete_status` tinyint NULL DEFAULT 0 COMMENT '删除状态',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '国家表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_coupon
-- ----------------------------
DROP TABLE IF EXISTS `jf_coupon`;
CREATE TABLE `jf_coupon`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '优惠卷编码：YHJ20251226123',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '优惠券名称',
  `amount` decimal(20, 2) NOT NULL COMMENT '优惠券额度（元）',
  `validity_type` int NOT NULL DEFAULT 1 COMMENT '有效期类型：1=长期有效，2=领取后使用，3=指定到期日',
  `expire_time` datetime NULL DEFAULT NULL COMMENT '到期日期',
  `after_receive_days` int NULL DEFAULT NULL COMMENT '领取后指定天数内使用',
  `apply_type` int NOT NULL DEFAULT 1 COMMENT '适用类型：1=剪办优惠',
  `apply_scope` int NOT NULL DEFAULT 1 COMMENT '适用商品范围：1=全部商品',
  `cutting_weight_limit` decimal(18, 2) NOT NULL DEFAULT 10.00 COMMENT '剪办重量上限（kg/次）',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注说明',
  `status` int NOT NULL DEFAULT 1 COMMENT '状态：1=生效中，2=已失效',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=启用，0=停用',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 60 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '优惠券表（优惠券制作）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_coupon_acquisition_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_coupon_acquisition_record`;
CREATE TABLE `jf_coupon_acquisition_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `coupon_template_id` bigint NOT NULL COMMENT '券模板ID（关联jf_coupon_customer）',
  `coupon_id` bigint NOT NULL COMMENT '优惠券ID（唯一标识一张优惠券）',
  `coupon_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '优惠券名称',
  `issued_quota` decimal(12, 2) NOT NULL COMMENT '发放优惠券额度（元）',
  `used_quota` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '已使用额度（元）',
  `frozen_quota` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '冻结额度（元）',
  `remaining_quota` decimal(12, 2) NOT NULL COMMENT '剩余可用额度（元）',
  `validity_type` int NOT NULL COMMENT '有效期类型（1-长期有效；2-领取后使用；3-指定到期日）',
  `issuance_time` datetime NOT NULL COMMENT '发放时间',
  `expiration_time` datetime NOT NULL COMMENT '到期时间',
  `applicable_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '适用类型',
  `color_weight_requirement` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '剪办颜色/重量要求',
  `applicable_product_range` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '适用商品范围（如：商品ID列表、全品类）',
  `acquisition_channel` int NULL DEFAULT NULL COMMENT '获取途径（1-优惠券发放；2-优惠券活动；3-数据迁移；4-客户转介绍）',
  `acquisition_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '获取途径活动号',
  `acquisition_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '获取途径活动单号',
  `coupon_status` int NOT NULL COMMENT '优惠券状态（1-使用中；2-已过期；3-已使用）',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改人',
  `updated_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除状态',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_coupon_id`(`coupon_id` ASC) USING BTREE COMMENT '优惠券ID唯一约束',
  INDEX `idx_coupon_template_id`(`coupon_template_id` ASC) USING BTREE COMMENT '券模板ID索引',
  INDEX `idx_issuance_time`(`issuance_time` ASC) USING BTREE COMMENT '发放时间索引',
  INDEX `idx_expiration_time`(`expiration_time` ASC) USING BTREE COMMENT '到期时间索引',
  INDEX `idx_coupon_status`(`coupon_status` ASC) USING BTREE COMMENT '优惠券状态索引'
) ENGINE = InnoDB AUTO_INCREMENT = 5299 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '优惠券获取记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_coupon_activity
-- ----------------------------
DROP TABLE IF EXISTS `jf_coupon_activity`;
CREATE TABLE `jf_coupon_activity`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `code` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '编码',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '优惠券活动名称（1-30位）',
  `start_time` datetime NOT NULL COMMENT '活动开始时间',
  `end_time` datetime NOT NULL COMMENT '活动结束时间，必须大于开始时间',
  `condition_type` int NOT NULL DEFAULT 1 COMMENT '发放条件类型：1=累计销售重量',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注说明',
  `status` int NOT NULL DEFAULT 0 COMMENT '活动状态：1=待开始，2=进行中，3=已结束，4=已取消',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=启用，0=停用',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '优惠券条件触发活动主表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_coupon_activity_step
-- ----------------------------
DROP TABLE IF EXISTS `jf_coupon_activity_step`;
CREATE TABLE `jf_coupon_activity_step`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `coupon_activity_id` bigint NOT NULL COMMENT '关联活动ID',
  `condition_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '条件名称，如“A类客户”',
  `step_order` int NOT NULL COMMENT '阶梯序号，从1开始',
  `min_weight` decimal(20, 2) NOT NULL COMMENT '起步吨数（下限）',
  `max_weight` decimal(20, 2) NOT NULL COMMENT '结束吨数（上限）',
  `coupon_id` bigint NOT NULL COMMENT '对应优惠券ID',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=启用，0=停用',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_coupon_activity`(`coupon_activity_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 67 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '优惠券条件活动阶梯规则表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_coupon_customer
-- ----------------------------
DROP TABLE IF EXISTS `jf_coupon_customer`;
CREATE TABLE `jf_coupon_customer`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '卷模板编码：KJ20251226123',
  `coupon_id` bigint NULL DEFAULT NULL COMMENT '优惠券ID',
  `customer_id` bigint NULL DEFAULT NULL COMMENT '关联客户ID',
  `amount` decimal(20, 2) NOT NULL COMMENT '优惠券额度（元）',
  `used_amount` decimal(20, 2) NOT NULL COMMENT '已使用额度',
  `available_amount` decimal(20, 2) NOT NULL COMMENT '可用额度',
  `frozen_amount` decimal(20, 2) NOT NULL COMMENT '冻结额度',
  `distribute_time` datetime NULL DEFAULT NULL COMMENT '发放时间',
  `expire_time` datetime NULL DEFAULT NULL COMMENT '到期时间',
  `status` int NOT NULL DEFAULT 0 COMMENT '优惠券状态：1=已作废，2=使用中，3=已使用，4=已过期',
  `acquire_source` int NOT NULL DEFAULT 0 COMMENT '获取途径：1=优惠券发放，2=优惠券活动，3=数据迁移，4=客户转介绍',
  `acquire_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '获取途径名称',
  `acquire_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '获取途径单号',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=启用，0=停用',
  `version` int NULL DEFAULT 0 COMMENT '版本号',
  `sign_code` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '校验码',
  `abandon_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作废人',
  `abandon_time` datetime NULL DEFAULT NULL COMMENT '作废时间',
  `abandon_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '作废原因',
  `acquire_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '获取途径备注，用于存拼接后的字段，防止连表查询',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_customer`(`customer_id` ASC) USING BTREE,
  INDEX `idx_coupon`(`coupon_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5390 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '优惠卷与客户关联表[卷模板]' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_coupon_customer_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_coupon_customer_record`;
CREATE TABLE `jf_coupon_customer_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `coupon_customer_id` bigint NOT NULL COMMENT '优惠券客户记录主键',
  `coupon_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '优惠券编码',
  `customer_id` bigint NULL DEFAULT NULL COMMENT '客户ID',
  `change_type` tinyint NOT NULL COMMENT '变动类型：1=冻结，2=释放，3=使用',
  `change_amount` decimal(18, 2) NOT NULL COMMENT '变动金额',
  `pre_available` decimal(18, 2) NULL DEFAULT NULL COMMENT '变动前可用额度',
  `post_available` decimal(18, 2) NULL DEFAULT NULL COMMENT '变动后可用额度',
  `pre_frozen` decimal(18, 2) NULL DEFAULT NULL COMMENT '变动前冻结额度',
  `post_frozen` decimal(18, 2) NULL DEFAULT NULL COMMENT '变动后冻结额度',
  `pre_used` decimal(18, 2) NULL DEFAULT NULL COMMENT '变动前已用额度',
  `post_used` decimal(18, 2) NULL DEFAULT NULL COMMENT '变动后已用额度',
  `related_business_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联业务单号（销售单号）',
  `operate_people` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作人',
  `operate_time` datetime NULL DEFAULT NULL COMMENT '操作时间',
  `change_reason` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '变动原因',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_coupon_customer_id`(`coupon_customer_id` ASC) USING BTREE,
  INDEX `idx_related_business_code`(`related_business_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '客户优惠券额度资金变动流水' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_coupon_detail
-- ----------------------------
DROP TABLE IF EXISTS `jf_coupon_detail`;
CREATE TABLE `jf_coupon_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `coupon_distribute_id` bigint NULL DEFAULT NULL COMMENT '优惠券发放ID',
  `coupon_id` bigint NULL DEFAULT NULL COMMENT '优惠券ID',
  `customer_id` bigint NULL DEFAULT NULL COMMENT '关联客户ID',
  `per_user_count` int NOT NULL DEFAULT 1 COMMENT '每人发放数量，默认1',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=启用，0=停用',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_coupon_distribute`(`coupon_distribute_id` ASC) USING BTREE,
  INDEX `idx_customer`(`customer_id` ASC) USING BTREE,
  INDEX `idx_coupon`(`coupon_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 119 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '优惠券发放表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_coupon_distribute
-- ----------------------------
DROP TABLE IF EXISTS `jf_coupon_distribute`;
CREATE TABLE `jf_coupon_distribute`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '优惠券活动id（编码）',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '优惠券活动名称',
  `type` int NOT NULL DEFAULT 1 COMMENT '发放条件类型：1=直接发放',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注说明',
  `status` int NOT NULL DEFAULT 1 COMMENT '活动状态：1=待审核，2=审核通过，3=审核不通过',
  `audit_remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核备注备注说明',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=启用，0=停用',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `auditer` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 61 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '优惠券发放活动表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_coupon_usage_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_coupon_usage_record`;
CREATE TABLE `jf_coupon_usage_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `sales_order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '出货销售单号',
  `coupon_template_id` bigint NOT NULL COMMENT '券模板ID（关联优惠券模板表）',
  `coupon_quota` decimal(12, 2) NOT NULL COMMENT '优惠券额度（元）',
  `remaining_quota` decimal(12, 2) NOT NULL COMMENT '剩余可用额度（元）',
  `deduction_quota` decimal(12, 2) NOT NULL COMMENT '本次减扣优惠券额度（元）',
  `use_time` datetime NULL DEFAULT NULL COMMENT '使用时间',
  `status` int NULL DEFAULT NULL COMMENT '使用状态：1=已使用，2=已取消',
  `return_time` datetime NULL DEFAULT NULL COMMENT '取消时间',
  `sales_return_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售退货单',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改人',
  `updated_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除状态',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sales_order_no`(`sales_order_no` ASC) USING BTREE COMMENT '出货销售单号索引，关联销售单查询',
  INDEX `idx_coupon_template_id`(`coupon_template_id` ASC) USING BTREE COMMENT '券模板ID索引，统计同模板优惠券使用情况'
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '优惠券使用记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_coupon_use_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_coupon_use_record`;
CREATE TABLE `jf_coupon_use_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `coupon_customer_id` bigint NOT NULL COMMENT '卷模板ID',
  `delivery_order_id` bigint NOT NULL COMMENT '出货单ID',
  `available_amount` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '剩余可用额度',
  `deducted_amount` decimal(20, 2) NOT NULL DEFAULT 0.00 COMMENT '本次减扣优惠券金额',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=启用，0=停用',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_delivery_order`(`delivery_order_id` ASC) USING BTREE,
  INDEX `idx_coupon_customer`(`coupon_customer_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '优惠卷使用记录表(作废)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_craft_wastage
-- ----------------------------
DROP TABLE IF EXISTS `jf_craft_wastage`;
CREATE TABLE `jf_craft_wastage`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `dyeing_wastage_ratio` decimal(20, 2) NULL DEFAULT NULL COMMENT '染整总损%',
  `theory_wastage_ratio` decimal(20, 2) NULL DEFAULT NULL COMMENT '理论总损',
  `weight_per_roll` decimal(20, 2) NULL DEFAULT NULL COMMENT '单疋重',
  `fabric_composition` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '布面料材质成分（中文）',
  `wastage_ratio` decimal(20, 2) NULL DEFAULT NULL COMMENT '损耗率',
  `wastage_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '损耗类型',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '工艺损耗' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_currency
-- ----------------------------
DROP TABLE IF EXISTS `jf_currency`;
CREATE TABLE `jf_currency`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '编码',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易币种名称',
  `country` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属国家',
  `rate` decimal(18, 6) NULL DEFAULT NULL COMMENT '汇率',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 (0:禁用, 1:启用)',
  `sort` int NULL DEFAULT 50 COMMENT '排序值',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 834 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '交易币种' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_customer
-- ----------------------------
DROP TABLE IF EXISTS `jf_customer`;
CREATE TABLE `jf_customer`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `created_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人（要么为空，要么在用户表里必须有对应的值，不然站内信逻辑会报错）',
  `created_time` datetime NOT NULL COMMENT '创建时间（不能为空，新增对账单有业务逻辑）',
  `updated_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改人',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态',
  `crm_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户编号',
  `abbreviation` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户简称',
  `company` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '公司全称(客户名称)',
  `detailed_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '详细地址',
  `trader_id` bigint NOT NULL COMMENT '贸易商id',
  `business_group` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务组别',
  `business_manager` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务经理',
  `store_sales` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '门店销售',
  `order_checker` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '跟单人',
  `customer_level_id` bigint NOT NULL DEFAULT 5 COMMENT '客户等级',
  `ordering_discount_methods` int NOT NULL DEFAULT 1 COMMENT '下单优惠方式(1-先优惠；2-后优惠)',
  `customer_account_id` bigint NOT NULL COMMENT '客户账户余额(关联jf_customer_account)',
  `quota_customer_id` bigint NULL DEFAULT NULL COMMENT '授信额度(关联jf_contract_quota_customer)',
  `control_account_period_id` bigint NULL DEFAULT NULL COMMENT '结算方式(账期管理)',
  `allowed_place_order` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否允许下单',
  `brand_id` bigint NULL DEFAULT NULL COMMENT '品牌系列',
  `brand_parent` tinyint(1) NULL DEFAULT 0 COMMENT '品牌父级',
  `customer_base_id` bigint NULL DEFAULT NULL COMMENT '客户主体id',
  `customer_base` tinyint(1) NULL DEFAULT 0 COMMENT '客户主体',
  `is_overdue` tinyint(1) NULL DEFAULT 0 COMMENT '是否逾期',
  `is_over_sea` tinyint(1) NULL DEFAULT 0 COMMENT '是否海外',
  `type` int NOT NULL DEFAULT 1 COMMENT '类别（1:直接客户  2：内部客户）',
  `trade_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '贸易类型',
  `attribute` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '属性',
  `enterprise_nature` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '企业性质',
  `per_kilogram_freight_cost` decimal(18, 2) NULL DEFAULT NULL COMMENT '单公斤运费',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态 0-禁用；1-启用；',
  `contact` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `start_transaction_time` date NULL DEFAULT NULL COMMENT '往来开始时间',
  `end_transaction_time` date NULL DEFAULT NULL COMMENT '往来结束时间',
  `quality_grade_id` bigint NULL DEFAULT NULL COMMENT '质量等级',
  `production_scale` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产规模',
  `business_model` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '经营模式',
  `customer_status` tinyint(1) NULL DEFAULT NULL COMMENT '客户状态',
  `fabric_usage` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '面料用量',
  `price_positioning` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '价格定位',
  `main_category` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主营类目',
  `product_style` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品风格',
  `importance_level` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '重要程度',
  `invoice_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开票类型',
  `perfect_identifying` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '完善标识',
  `logistics_information` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物流信息',
  `is_purchase_insurance` tinyint(1) NULL DEFAULT NULL COMMENT '是否购买保险',
  `approve_credit_limit` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '受理授信额度',
  `all_votes` int NULL DEFAULT NULL COMMENT '全票0-否；1-全票3%；2-全票6%',
  `total_net_weight` tinyint(1) NULL DEFAULT NULL COMMENT '全净重',
  `check_out_method` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结账方式',
  `is_not_in` tinyint(1) NOT NULL COMMENT '是否特批不入群',
  `delivery_note` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送货备注',
  `other_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其他备注',
  `memo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备忘',
  `insurance_guarantee_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '保险担保额度',
  `pay_form_id` bigint NOT NULL DEFAULT 1 COMMENT '支付形式id（不再关联表；1-现金支付，2-额度支付）[使用control_account_period表中的pay_form]',
  `province` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '省',
  `city` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '城市',
  `area` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区',
  `is_in` tinyint(1) NULL DEFAULT NULL COMMENT '是否入群',
  `quota` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '额度备注',
  `latest_sales` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最新销售备注',
  `insurance` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '保险备注',
  `is_delivery` tinyint(1) NULL DEFAULT NULL COMMENT '是否寄付',
  `customer_account_balance` decimal(18, 2) NULL DEFAULT NULL COMMENT '客户账户余额（作废）',
  `coupon_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '优惠券额度（作废）',
  `credit_line` decimal(18, 2) NULL DEFAULT NULL COMMENT '授信额度（作废）',
  `payment_method` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结算方式（作废）',
  `brand_series` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品牌系列（这个字段作废了，平台一直自动生成，上面有一个品牌系列）',
  `is_overseas` tinyint(1) NULL DEFAULT 0 COMMENT '是否海外（这个字段作废了，平台一直自动生成，上面有一个是否海外）',
  `crm_id` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'CRM客户id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_customer_overdue_candidate_status`(`delete_status` ASC, `is_overdue` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 235680 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '客户信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_customer_account
-- ----------------------------
DROP TABLE IF EXISTS `jf_customer_account`;
CREATE TABLE `jf_customer_account`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `customer_id` bigint NOT NULL COMMENT '客户id',
  `account_status` int NOT NULL DEFAULT 1 COMMENT '账户状态 ( 1:销售可用；2:销售禁用)',
  `available_balance` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '可用余额 (单位: 元)',
  `frozen_balance` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '冻结余额 (单位: 元)',
  `created_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  `version_no` int NULL DEFAULT 0 COMMENT '版本号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 131 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '客户账号信息' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_customer_account_detail
-- ----------------------------
DROP TABLE IF EXISTS `jf_customer_account_detail`;
CREATE TABLE `jf_customer_account_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `customer_account_id` bigint NOT NULL COMMENT '客户账号ID',
  `account_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账户名称',
  `transaction_type` tinyint(1) NOT NULL COMMENT '交易类型 (0:支出, 1:进账)',
  `transaction_method` int NOT NULL COMMENT '交易方式 (1=客户付款，2=销售单，3=订金释放，4=订金使用，5=年底返利结算)',
  `pre_balance` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '变动前账户余额',
  `amount` decimal(18, 2) NOT NULL COMMENT '收入/支出金额 (正数为收入，负数为支出)',
  `post_balance` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '变动后账户余额',
  `source_document` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '来源单据号',
  `operator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作人',
  `operation_time` datetime NOT NULL COMMENT '操作时间',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_customer_account`(`customer_account_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 25 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '客户账号详情（作废，使用jf_customer_balance_usage_record）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_customer_balance_usage_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_customer_balance_usage_record`;
CREATE TABLE `jf_customer_balance_usage_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `type` int NOT NULL COMMENT '类型（1-进账; 2-支出；3-冻结；4-释放）',
  `way` int NULL DEFAULT NULL COMMENT '方式（1-客户付款；2-定金；3-销售单；4-订金释放；5-订金使用；6-年底返利结算；7-退货单；8-退款单;9-核销单；10-收款单）',
  `before_change_account_balance` decimal(16, 2) NOT NULL COMMENT '变动前账号余额（元）',
  `income_expenditure` decimal(16, 2) NOT NULL COMMENT '使用金额（元）',
  `is_add` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否收入（正数为增加，负数为减少）',
  `change_account_balance` decimal(16, 2) NOT NULL COMMENT '变动后账户余额（元）',
  `source_documents` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '来源单据',
  `version_no` int NOT NULL DEFAULT 0 COMMENT '单据版本号（从0开始）',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '修改人',
  `updated_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除状态',
  `version` int NULL DEFAULT NULL COMMENT '版本号',
  `customer_id` bigint NOT NULL COMMENT '客户id（关联客户表）',
  `receipt_id` bigint NULL DEFAULT NULL COMMENT '进账单id（关联进账单表）(作废)',
  `change_type` int NULL DEFAULT NULL COMMENT '改变后的类型',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_customer_id`(`customer_id` ASC) USING BTREE COMMENT '客户id索引，优化客户余额记录查询',
  INDEX `idx_created_time`(`created_time` ASC) USING BTREE COMMENT '操作时间索引，优化时间范围查询',
  INDEX `idx_receipt_id`(`receipt_id` ASC) USING BTREE COMMENT '进账单id索引，关联进账单查询'
) ENGINE = InnoDB AUTO_INCREMENT = 2103749646486409219 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '客户详情-账户余额使用记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_customer_base
-- ----------------------------
DROP TABLE IF EXISTS `jf_customer_base`;
CREATE TABLE `jf_customer_base`  (
  `id` bigint NOT NULL COMMENT '主键',
