  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '客户主体表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_customer_color
-- ----------------------------
DROP TABLE IF EXISTS `jf_customer_color`;
CREATE TABLE `jf_customer_color`  (
