  `delete_status` tinyint NULL DEFAULT 0 COMMENT '删除状态',
  `equity_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '权益项',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '权益项说明',
  `equity_id` bigint NULL DEFAULT NULL COMMENT '权益项id',
  `get_method` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '获取方式',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '客户权益申请关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_customer_equity_operation_log
-- ----------------------------
DROP TABLE IF EXISTS `jf_customer_equity_operation_log`;
CREATE TABLE `jf_customer_equity_operation_log`  (
  `id` bigint NOT NULL COMMENT '主键',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新者',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作事项',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1' COMMENT '修改原因',
  `customer_level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '客户等级',
  `remain_reduction_opportunities` int NULL DEFAULT NULL COMMENT '剩余减免次数',
  `adjust_number` int NULL DEFAULT NULL COMMENT '调整次数',
  `equity_item_id` bigint NULL DEFAULT NULL COMMENT '权益项id',
  `customer_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '客户名称',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作内容',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '客户权益修改记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_customer_invoice_information
-- ----------------------------
DROP TABLE IF EXISTS `jf_customer_invoice_information`;
CREATE TABLE `jf_customer_invoice_information`  (
