-- ----------------------------
-- Table structure for jf_customer_level
-- ----------------------------
DROP TABLE IF EXISTS `jf_customer_level`;
CREATE TABLE `jf_customer_level`  (
  `id` bigint NOT NULL COMMENT '主键',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新者',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '客户等级名称',
  `min_sales` bigint NULL DEFAULT NULL COMMENT '最小年度销售量',
  `max_sales` bigint NULL DEFAULT NULL COMMENT '最大年度销售量',
  `discount_amount` decimal(31, 2) NULL DEFAULT NULL COMMENT '销售单价优惠金额',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '客户等级（id为1-5的数据不允许修改，业务逻辑写死）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_customer_level_adjustment_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_customer_level_adjustment_record`;
CREATE TABLE `jf_customer_level_adjustment_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `original_level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '调整前客户等级',
  `adjusted_level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '调整后客户等级',
  `adjustment_time` datetime NOT NULL COMMENT '调整时间',
  `adjustment_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '调整类型（1-自然年-返利结算；2-战略协议到期-返利结算；3-签署战略协议；4-OA申请；5-初始化客户等级）',
  `source_document` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '来源单据',
  `customer_id` bigint NULL DEFAULT NULL COMMENT '客户id',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '创建人',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '修改人',
  `updated_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除状态',
  `start_valid_date` date NULL DEFAULT NULL COMMENT '有效期开始时间',
  `end_valid_date` date NULL DEFAULT NULL COMMENT '有效期结束时间',
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请人id',
  `center_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '所属中心',
  `dept_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '所属部门',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `status` int NULL DEFAULT NULL COMMENT '状态（1-审核中；2-审核通过；3-审核不通过）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_adjustment_time`(`adjustment_time` ASC) USING BTREE COMMENT '调整时间索引',
  INDEX `idx_source_document`(`source_document` ASC) USING BTREE COMMENT '来源单据索引'
) ENGINE = InnoDB AUTO_INCREMENT = 25 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '客户等级变更记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_customer_merge_discounts_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_customer_merge_discounts_record`;
CREATE TABLE `jf_customer_merge_discounts_record`  (
  `id` bigint NOT NULL COMMENT '主键',
