  `effect_time` datetime NULL DEFAULT NULL COMMENT '生效时间',
  `relate_oa_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联OA编码',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态',
  `applicant` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '申请人',
  `apply_time` datetime NULL DEFAULT NULL COMMENT '申请时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '客户合并优惠记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_customer_overdue_tag_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_customer_overdue_tag_record`;
CREATE TABLE `jf_customer_overdue_tag_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `type` int NULL DEFAULT NULL COMMENT '类型（1-标记；2-解除）',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '原因',
  `handle_time` datetime NULL DEFAULT NULL COMMENT '处理时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '修改人',
  `updated_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除状态',
  `customer_id` bigint NULL DEFAULT NULL COMMENT '客户id',
  `overdue_rules_id` bigint NULL DEFAULT NULL COMMENT '逾期规则id',
  `control_account_period_id` bigint NULL DEFAULT NULL COMMENT '账期id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_type`(`type` ASC) USING BTREE COMMENT '标签类型索引，按类型统计逾期情况'
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '逾期标签记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_customer_quality_grade
-- ----------------------------
