-- ----------------------------
-- Table structure for jf_customer_statement
-- ----------------------------
DROP TABLE IF EXISTS `jf_customer_statement`;
CREATE TABLE `jf_customer_statement`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '借贷：1=借，0=贷',
  `fee_item_id` bigint NULL DEFAULT NULL COMMENT '费项id',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
  `company` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '公司全称(客户名称)',
  `supplier` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商',
  `trader_id` bigint NULL DEFAULT NULL COMMENT '贸易商id',
  `trader` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '贸易商',
  `brand` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品牌',
  `final_factory` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最终厂家',
  `final_factory_id` bigint NULL DEFAULT NULL COMMENT '最终厂家id',
  `voucher_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '凭证号',
  `style_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '款号',
  `transaction_date` date NOT NULL COMMENT '交易日期',
  `fee_category_id` bigint NULL DEFAULT NULL COMMENT '单据类型id',
  `debit_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '借方金额',
  `credit_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '贷方金额',
  `balance` decimal(18, 2) NOT NULL COMMENT '余额',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `is_written_off` tinyint(1) NULL DEFAULT NULL COMMENT '是否核销',
  `fee_item_type` int NULL DEFAULT NULL COMMENT '费项类型（1=费项，2=税费）',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=已删除，0=未删除',
  `statement_id` bigint NULL DEFAULT NULL COMMENT '对账单id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 908 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '客户对账单表' ROW_FORMAT = Dynamic;

-- ----------------------------
