  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '布种' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_fee_bill
-- ----------------------------
DROP TABLE IF EXISTS `jf_fee_bill`;
CREATE TABLE `jf_fee_bill`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号(费项池的code)',
  `fee_category_id` bigint NOT NULL COMMENT '费项类别ID',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
  `currency_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '币种代码',
  `currency_rate` decimal(10, 6) NULL DEFAULT NULL COMMENT '币种汇率',
  `invoice_type` int NULL DEFAULT NULL COMMENT '开票类型：0=不开票，1=普票，2=专票',
  `tax_rate` decimal(5, 2) NOT NULL DEFAULT 0.00 COMMENT '税率',
  `bill_date` date NULL DEFAULT NULL COMMENT '开单日期',
  `trader_id` bigint NULL DEFAULT NULL,
  `trader` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '贸易商',
  `customer_short_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户简称(往来单位)',
  `company` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '公司全称(单位全称)',
  `final_manufacturer` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最终厂家',
  `business_group` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务组别',
  `business_manager` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务经理',
  `store_sales` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '门店销售',
  `receipt_contact` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人',
  `receipt_contact_way` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系方式',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注说明',
  `associate_sales_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联销售单号（其他费项单用到）',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  `delivery_address_id` bigint NULL DEFAULT NULL COMMENT '送货地址id',
  `version` int NULL DEFAULT NULL COMMENT '版本号',
  `is_draft` int NOT NULL DEFAULT 1 COMMENT '0：草稿，1：正式',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unique_idx_code`(`code` ASC) USING BTREE,
  INDEX `idx_fee_category`(`fee_category_id` ASC) USING BTREE,
  INDEX `idx_customer`(`customer_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2004 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '费项单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_fee_bill_item
-- ----------------------------
DROP TABLE IF EXISTS `jf_fee_bill_item`;
CREATE TABLE `jf_fee_bill_item`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `fee_bill_id` bigint NOT NULL COMMENT '费项单（主表）ID',
  `fee_item_id` bigint NULL DEFAULT NULL COMMENT '费项ID',
  `fee_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '费项编码',
  `fee_category_id` bigint NOT NULL COMMENT '费项类型',
  `tax_rate` decimal(5, 2) NOT NULL COMMENT '税率',
  `tax_amount` decimal(12, 2) NOT NULL COMMENT '税费金额',
  `fee_item_amount` decimal(18, 2) NOT NULL COMMENT '费项金额',
  `collected_tax_amount` decimal(18, 2) NOT NULL COMMENT '已收税金（税费金额）',
  `invoiced_amount` decimal(18, 2) NOT NULL COMMENT '已开票金额（核销已开票金额）',
  `invoiced_tax_amount` decimal(18, 2) NOT NULL COMMENT '已开票税金（税率*核销已开票金额）',
  `refundable_amount` decimal(18, 2) NOT NULL COMMENT '可退税金额（费项金额-核销已开票金额）',
  `refundable_tax_amount` decimal(18, 2) NOT NULL COMMENT '可退税税金（税率*核销已开票金额）',
  `current_refund_amount` decimal(18, 2) NOT NULL COMMENT '本次退税费项金额（手动输入）',
  `current_refund_tax_amount` decimal(18, 2) NOT NULL COMMENT '本次退税税金（本次退税费项金额*税率）',
  `write_off_amount` decimal(18, 2) NOT NULL COMMENT '核销金额（作废）',
  `un_write_off_amount` decimal(18, 2) NOT NULL COMMENT '未核销金额（作废）',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  `fee_descript` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '费用描述',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_fee_bill`(`fee_bill_id` ASC) USING BTREE,
  INDEX `idx_fee_item`(`fee_item_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1320 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '单据-费项' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_fee_bill_responsibility
-- ----------------------------
DROP TABLE IF EXISTS `jf_fee_bill_responsibility`;
CREATE TABLE `jf_fee_bill_responsibility`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `fee_bill_id` bigint NOT NULL COMMENT '费项单id',
  `department` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '责任部门',
  `ratio` decimal(5, 2) NULL DEFAULT NULL COMMENT '责任比例 (%)',
  `deduction_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '责任扣费金额',
  `responsible_party` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '责任主体',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '承担主体加单号',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_fee_bill`(`fee_bill_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '单据-内部责任单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_fee_bill_sales_order
-- ----------------------------
DROP TABLE IF EXISTS `jf_fee_bill_sales_order`;
CREATE TABLE `jf_fee_bill_sales_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `fee_bill_id` bigint NULL DEFAULT NULL COMMENT '费项单（主表）ID',
  `sales_order_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `sales_order_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '销售单金额',
  `fee_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '费项金额',
  `tax_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '税率',
  `tax_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '税费金额',
  `fee_description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '费项描述',
  `unit_price_discount` decimal(12, 2) NULL DEFAULT NULL COMMENT '单价优惠金额',
  `discount_total_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '单价优惠金额',
  `write_off_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '核销金额',
  `un_write_off_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '未核销金额',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  `fee_item_id` bigint NULL DEFAULT NULL COMMENT '费项池（主表）ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_fee_bill`(`fee_bill_id` ASC) USING BTREE,
  INDEX `idx_sales_order`(`sales_order_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 732 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '单据-销售单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_fee_category
-- ----------------------------
DROP TABLE IF EXISTS `jf_fee_category`;
CREATE TABLE `jf_fee_category`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `prefix_code` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '费项单据编码前缀',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '费项名称',
  `is_engagement_write_off` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否参与核销 (0:否, 1:是)',
  `is_overdue_calculation` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否计算逾期 (0:否, 1:是)',
  `is_sales_order` tinyint(1) NULL DEFAULT 0 COMMENT '是否销售单可选(0:否, 1:是)',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态 (0:禁用, 1:启用)',
  `sort` int NULL DEFAULT 50 COMMENT '排序值',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  `receivable_direction` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'MANUAL' COMMENT '应收方向：DEBIT,CREDIT,MANUAL',
  `amount_sign` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0：不限制，1：正，2：负',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1043 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '费项管理（类型费项，此表id为1-20的数据不允许更改）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_fee_invoice_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_fee_invoice_record`;
CREATE TABLE `jf_fee_invoice_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `fee_item_id` bigint NULL DEFAULT NULL COMMENT '费项ID',
  `invoiced_quantity` decimal(18, 2) NULL DEFAULT NULL COMMENT '本次开票数量',
  `print_date` date NULL DEFAULT NULL COMMENT '打印日期',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_fee_item`(`fee_item_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '费项开票记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_fee_item
-- ----------------------------
DROP TABLE IF EXISTS `jf_fee_item`;
CREATE TABLE `jf_fee_item`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `fee_category_id` bigint NOT NULL COMMENT '费项类型id',
  `fee_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '费项（项目）编码',
  `trader_id` bigint NULL DEFAULT NULL COMMENT '贸易商id',
  `customer_id` bigint NOT NULL COMMENT '客户id',
  `customer_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户编码',
  `status` int NOT NULL DEFAULT 1 COMMENT '状态：1=待录入收款通知单，2=已加入收款通知单',
  `collection_notice_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联收款单号',
  `claim_status` int NOT NULL DEFAULT 1 COMMENT '认领单状态：1=待录入应收认领单，2=已加入应收认领单',
  `receivable_claim_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联应收认领单号',
  `payment_status` int NOT NULL DEFAULT 1 COMMENT '收款状态：0=作废，1=未收款，2=部分收款，3=已收款',
  `is_over_due` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否计算逾期 (0:否, 1:是)',
  `sales_return_quantity` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '销售/退货数量',
  `invoiced_quantity` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '已开票数量',
  `un_invoiced_quantity` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '未开票数量',
  `fee_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '费项金额',
  `refund_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '费项退款金额',
  `received_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '已收金额(已核销金额为主)',
  `write_off_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '核销金额',
  `un_write_off_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '未核销金额',
  `fee_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '费项备注',
  `write_off_invoiced_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '核销已开票金额',
  `review_write_off_invoice_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '核销待审核开票金额(弃用)',
  `un_write_off_invoiced_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '核销未开票金额',
  `invoice_status` int NULL DEFAULT 1 COMMENT '开票状态 (0=不需开票, 1=未开票, 2=部分开票，3=已开票)',
  `invoice_occupy_flag` int NOT NULL DEFAULT 1 COMMENT '状态：1=待录入发票申请，2=已加入发票申请',
  `invoice_application_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联发票申请单号',
  `is_tax_included` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否含税：1=是，0=否',
  `tax_rate` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '税率',
  `tax_status` int NOT NULL DEFAULT 1 COMMENT '税费状态：1=待录入收款通知单，2=已加入收款通知单',
  `tax_collection_notice_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联收款单号',
  `tax_claim_status` int NOT NULL DEFAULT 1 COMMENT '税费认领单状态：1=待录入应收认领单，2=已加入应收认领单',
  `tax_receivable_claim_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联应收认领单号',
  `tax_payment_status` int NULL DEFAULT 1 COMMENT '税费缴费状态 (0=作废，1=未收款，2=部分收款，3=已收款)',
  `tax_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '税额',
  `tax_refund_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '退税金额',
  `tax_received_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '已收税额(已核销金额为主)',
  `tax_write_off_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '核销税额',
  `tax_un_write_off_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '未核销税额',
  `tax_payment_time` datetime NULL DEFAULT NULL COMMENT '税费缴费时间',
  `tax_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '税费备注',
  `is_write_off` tinyint(1) NULL DEFAULT 0 COMMENT '是否需要核销 (0:否, 1:是)',
  `tax_bill_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '税费单',
  `sales_order_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售单',
  `related_business_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联业务单据编码',
  `delivery_date` date NULL DEFAULT NULL COMMENT '发货日期',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注 格式：运费-税费',
  `last_payment_date` datetime NULL DEFAULT NULL COMMENT '最后付款时间（该时间  +  最后付款期限 = 逾期时间）',
  `last_due_date` datetime NULL DEFAULT NULL COMMENT '最后应付时间 （逾期时间 ，到该时间未付款金额 > 逾期偏差值 ，标记为逾期[over_due]）',
  `over_due` tinyint(1) UNSIGNED ZEROFILL NULL DEFAULT 0 COMMENT '是否逾期 (0:否, 1:是)',
  `over_due_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '逾期金额',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=已删除，0=未删除',
  `curency_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '币种编码',
  `currency_rate` decimal(18, 2) NULL DEFAULT 1.00 COMMENT '币种汇率',
  `is_sales_order` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否由销售单出数后自动生成：0=手动生成，1=自动生成',
  `is_debt_transfer` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否债务转移：0=否，1=是',
  `version_no` int NULL DEFAULT 1 COMMENT '版本号',
  `write_off_occupy_flag` int NULL DEFAULT 1 COMMENT '应收核销单占用状态：1=待录入应收核销单，2=已加入应收核销单。手动新增核销单的场景',
  `write_off_occupy_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '当前占用的应收核销单编码',
  `tax_write_off_occupy_flag` int NULL DEFAULT 1 COMMENT '应收核销单占用状态：1=待录入应收核销单，2=已加入应收核销单。手动新增核销单的场景',
  `tax_write_off_occupy_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '当前占用的应收核销单编码',
  `source_doc_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '源单类型',
  `source_doc_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '源单编号',
  `source_doc_id` bigint NULL DEFAULT NULL COMMENT '源单ID',
  `source_doc_line_id` bigint NULL DEFAULT NULL COMMENT '源单行ID',
  `refund_occupy_flag` int NULL DEFAULT 1 COMMENT '应收退款单占用状态：1=待录入应收退款单，2=已加入应收退款单',
  `refund_occupy_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '当前占用的应收退款单编码',
  `tax_refund_occupy_flag` int NULL DEFAULT 1 COMMENT '应收退款单占用状态：1=待录入应收退款单，2=已加入应收退款单',
  `tax_refund_occupy_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '当前占用的应收退款单编码',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `key_customer_id`(`customer_id` ASC) USING BTREE,
  INDEX `idx_fee_item_overdue_due`(`delete_status` ASC, `is_over_due` ASC, `last_due_date` ASC) USING BTREE,
  INDEX `idx_fee_item_overdue_actual`(`delete_status` ASC, `is_over_due` ASC, `over_due` ASC) USING BTREE,
  INDEX `idx_fee_item_customer_overdue_due`(`customer_id` ASC, `delete_status` ASC, `is_over_due` ASC, `last_due_date` ASC) USING BTREE,
  INDEX `idx_fee_customer_overdue`(`customer_id` ASC, `delete_status` ASC, `is_over_due` ASC, `over_due` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2103345217727737860 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '费项明细(费项池)' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_fee_item_flow
-- ----------------------------
DROP TABLE IF EXISTS `jf_fee_item_flow`;
CREATE TABLE `jf_fee_item_flow`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `fee_item_id` bigint NOT NULL COMMENT '费项ID',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
  `flow_type` int NOT NULL COMMENT '流水类型（1=收款确认，2=核销扣减，3=核销撤销，4=冻结，5=解冻，6=退款，8=增加税费，9=退税）',
  `before_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '变更前金额（单位：元）',
  `change_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '变更金额（正数增加，负数减少）（单位：元）',
  `after_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '变更后金额（单位：元）',
  `before_tax_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '税费变更前金额（单位：元）',
  `change_tax_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '税费变更金额（单位：元）',
  `after_tax_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '税费变更后金额（单位：元）',
  `source_doc_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源单据类型',
  `source_doc_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源单据编码',
  `source_doc_id` bigint NULL DEFAULT NULL COMMENT '来源单据ID',
  `occurred_time` datetime NULL DEFAULT NULL COMMENT '业务发生时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注说明',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除（0:否，1:是）',
  `version_no` int NULL DEFAULT 0 COMMENT '版本号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_fee_item_id`(`fee_item_id` ASC) USING BTREE COMMENT '费项ID索引',
  INDEX `idx_customer_id`(`customer_id` ASC) USING BTREE COMMENT '客户ID索引',
  INDEX `idx_occurred_time`(`occurred_time` ASC) USING BTREE COMMENT '业务发生时间索引',
  INDEX `idx_source_doc`(`source_doc_type` ASC, `source_doc_id` ASC) USING BTREE COMMENT '来源单据复合索引'
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '费项流水表（审计日志）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
