-- ----------------------------
-- Table structure for jf_first_trial_cut_discount_usage_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_first_trial_cut_discount_usage_record`;
CREATE TABLE `jf_first_trial_cut_discount_usage_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `shipment_sales_order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '出货销售单号',
  `product_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品编号',
  `product_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品名称',
  `sales_color_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '销售色号',
  `color` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '颜色',
  `sales_unit_price` decimal(12, 2) NOT NULL COMMENT '销售单价（元）',
  `sales_weight` decimal(10, 2) NULL DEFAULT NULL COMMENT '销售重量（kg）',
  `sales_amount` decimal(15, 2) NOT NULL COMMENT '销售金额（元）',
  `discount_rate` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '折扣率（如0.08代表8%）',
  `discounted_amount` decimal(15, 2) NOT NULL COMMENT '折扣后金额（元）',
  `order_time` datetime NOT NULL COMMENT '下单时间',
  `order_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '订单状态（1-待付款；2-待拣货；3-待出库；4-配送中；5-已完成；6-已取消）',
  `discount_activity_id` bigint NULL DEFAULT NULL COMMENT '优惠活动ID（关联优惠活动表）',
  `activity_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '活动名称',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人',
  `created_time` datetime NOT NULL COMMENT '创建时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修改人',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除状态',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_discount_activity_id`(`discount_activity_id` ASC) USING BTREE COMMENT '优惠活动ID索引',
  INDEX `idx_shipment_sales_order_no`(`shipment_sales_order_no` ASC) USING BTREE COMMENT '出货销售单号索引',
  INDEX `idx_product_code`(`product_code` ASC) USING BTREE COMMENT '商品编号索引',
  INDEX `idx_order_time`(`order_time` ASC) USING BTREE COMMENT '下单时间索引'
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '首条试裁优惠使用记录表(弃用)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_goods
-- ----------------------------
DROP TABLE IF EXISTS `jf_goods`;
CREATE TABLE `jf_goods`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '名称',
  `spu` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '编码',
  `english_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '英文名',
  `prod_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开发编码',
  `record_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备案编码',
  `previous_goods_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '升级前商品号',
  `type` int NULL DEFAULT NULL COMMENT '商品类型 1：主身,2：罗纹',
  `spu_category_id` bigint NULL DEFAULT NULL COMMENT '销售类型',
  `fabric_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '布种编码',
  `fabric_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '布种名称',
  `source_product` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源产品',
  `discount_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '折让状态(0:不折让，1：折让中)',
  `discount_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT '折让价格',
  `raw_fabric_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '默认坯布编码',
  `finish_product_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '默认成品编码',
  `composition` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成分',
  `product_type_id` bigint NULL DEFAULT NULL COMMENT '产品类别id（产品品类）',
  `fabric_composition_id` bigint NULL DEFAULT NULL COMMENT '面料种类id（产品种类）',
  `fabric_id` bigint NULL DEFAULT NULL COMMENT '旧erp系统的商品Id',
  `finish_width` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '封度',
  `gsm` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '克重',
  `interval` decimal(20, 2) NULL DEFAULT NULL COMMENT '间距',
  `specs` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格',
  `dyeing_method_id` bigint NULL DEFAULT NULL COMMENT '染色类别Id',
  `quality_standard_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '质量标准',
  `application_scope_id` bigint NULL DEFAULT NULL COMMENT '应用范围id',
  `application_season_id` bigint NULL DEFAULT NULL COMMENT '适用季节id',
  `package_paper_tube_id` bigint NULL DEFAULT NULL COMMENT '包装纸筒id',
  `package_plastic_bag_id` bigint NULL DEFAULT NULL COMMENT '包装胶袋id',
  `is_new_goods` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否新品',
  `recommend` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否主推',
  `no_sampling` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否禁止剪办',
  `prod_craft` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产工艺',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '上架状态 1：上架,0：下架',
  `goods_category_id` bigint NULL DEFAULT NULL COMMENT '商品品类ID',
  `cylinder_roll` tinyint(1) NOT NULL DEFAULT 1 COMMENT '圆筒卷',
  `single_weight` decimal(20, 2) NULL DEFAULT NULL COMMENT '单疋重量',
  `grey_max_level` int NULL DEFAULT NULL COMMENT '坯布库存上限',
  `stock_max_level` int NULL DEFAULT NULL COMMENT '库存上限(色布库存上限)',
  `stock_min_level` int NULL DEFAULT NULL COMMENT '库存下限',
  `factory_price` decimal(20, 2) NULL DEFAULT NULL COMMENT '出厂价',
  `sales_price` decimal(20, 2) NULL DEFAULT NULL COMMENT '销售价',
  `scatter_addition` decimal(20, 2) NULL DEFAULT NULL COMMENT '散剪加价',
  `suspend_time` datetime NULL DEFAULT NULL COMMENT '下架日期',
  `in_stock_date` date NULL DEFAULT NULL COMMENT '现货日期',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除',
  `product_property_id` bigint NULL DEFAULT NULL COMMENT '布类Id（产品属性）对应表jf_fabric_category',
  `product_date` date NULL DEFAULT NULL COMMENT '上架日期,来自旧erp接口',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `key_spu`(`spu` ASC, `delete_status` ASC) USING BTREE,
  INDEX `idx_other_code`(`prod_code` ASC, `record_code` ASC) USING BTREE,
  INDEX `idx_code`(`spu` ASC) USING BTREE,
  INDEX `idx_name`(`name` ASC) USING BTREE,
  INDEX `idx_type`(`spu_category_id` ASC) USING BTREE,
  INDEX `idx_application_scope`(`application_scope_id` ASC) USING BTREE,
  INDEX `idx_application_season`(`application_season_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11701 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品' ROW_FORMAT = DYNAMIC;

