-- ----------------------------
DROP TABLE IF EXISTS `jf_income_bill`;
CREATE TABLE `jf_income_bill`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '进账单号',
  `trader_id` bigint NOT NULL COMMENT '贸易商ID',
  `collection_account_id` bigint NOT NULL COMMENT '收款账号ID',
  `keep_accounts_time` date NULL DEFAULT NULL COMMENT '记账时间',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者（制单人）',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  `confirm` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认人',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认时间',
  `claim_status` int NULL DEFAULT NULL COMMENT '认领状态（1：待认领；2：部分认领；3：全部认领）',
  `confirm_status` int NULL DEFAULT NULL COMMENT '确认状态（1：待确认；2：已确认）',
  `currency_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易币种编码',
  `currency_rate` decimal(18, 6) NULL DEFAULT NULL COMMENT '币种汇率',
  `collection_total_amount` decimal(18, 2) NOT NULL COMMENT '收款合计金额',
  `currency_id` bigint NOT NULL COMMENT '交易币种ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_collection_account`(`collection_account_id` ASC) USING BTREE,
  INDEX `idx_trader`(`trader_id` ASC) USING BTREE,
  INDEX `idx_currency`(`currency_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 706 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '进账单' ROW_FORMAT = DYNAMIC;

