-- ----------------------------
-- Table structure for jf_inventory_batch_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_inventory_batch_record`;
CREATE TABLE `jf_inventory_batch_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `inventory_id` bigint NULL DEFAULT NULL COMMENT '库存明细ID',
  `sku` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'sku',
  `trader_id` bigint NOT NULL COMMENT '贸易商ID',
  `business_group` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务组别,销售员名称/门市组',
  `inventory_org` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '库存组织',
  `inventory_count` int NULL DEFAULT NULL COMMENT '库存条数',
  `available_count` int NULL DEFAULT 0 COMMENT '可用条数',
  `frozen_count` int NOT NULL DEFAULT 0 COMMENT '冻结条数',
  `is_3day` tinyint NULL DEFAULT 0 COMMENT '是否超3天',
  `order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单号',
  `type` int NULL DEFAULT NULL COMMENT '1=现货',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  `version_no` int NULL DEFAULT 1 COMMENT '版本号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_inventory`(`inventory_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 228 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '现货库存入库-批次记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_inventory_frozen_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_inventory_frozen_record`;
CREATE TABLE `jf_inventory_frozen_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `inventory_id` bigint NULL DEFAULT NULL COMMENT '库存明细ID',
  `sales_order_id` bigint NULL DEFAULT NULL COMMENT '销售单ID',
  `modify_version_no` int NULL DEFAULT NULL COMMENT '销售单版本号',
  `sku` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'sku',
  `trader_id` bigint NOT NULL COMMENT '贸易商ID',
  `business_group` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务组别,销售员名称/门市组',
  `inventory_org` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '库存组织',
  `cus_order_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客订备货单号',
  `inventory_type` int NOT NULL DEFAULT 0 COMMENT '库存类型(1:寄售,2:可用)',
  `pre_change_count` int NOT NULL DEFAULT 0 COMMENT '冻结前条数',
  `change_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '冻结类型 (0:冻结, 1:释放)',
  `change_count` int NOT NULL DEFAULT 0 COMMENT '冻结条数',
  `post_change_count` int NOT NULL DEFAULT 0 COMMENT '冻结后条数',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_inventory`(`inventory_id` ASC) USING BTREE,
  INDEX `idx_sales_order`(`sales_order_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2104017800915705859 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '库存冻结记录-销售单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_inventory_movement_idempotent
-- ----------------------------
DROP TABLE IF EXISTS `jf_inventory_movement_idempotent`;
CREATE TABLE `jf_inventory_movement_idempotent`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `idempotency_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '幂等键=主体类型|主体ID|变动类型|关联单号|事件ID(use的WMS请求号)',
  `subject_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主体类型(InventorySubjectType.name): BUSINESS/CONSIGNMENT/BATCH',
  `subject_id` bigint NOT NULL COMMENT '库存/批次主键',
  `movement_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '变动类型(InventoryMovementType.name): FREEZE/RELEASE/USE',
  `related_business_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '关联业务单号(订单号)',
  `request_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '幂等令牌nonce: use=WMS出库请求号; freeze/release=调用方派生(订单号+变动+主体); 空时引擎未做幂等',
  `quantity` int NOT NULL COMMENT '变动数量',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_inventory_movement_idem`(`idempotency_key` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16648 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '库存数量变动幂等去重表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_inventory_organization
-- ----------------------------
DROP TABLE IF EXISTS `jf_inventory_organization`;
CREATE TABLE `jf_inventory_organization`  (
  `recno` int NULL DEFAULT NULL COMMENT '记录编号（原始行号）',
  `id` int NULL DEFAULT NULL COMMENT '组织ID',
  `code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '组织编码',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '组织名称',
  `local_id` int NULL DEFAULT NULL COMMENT '本地ID',
  `local_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '本地名称',
  `home_id` int NULL DEFAULT NULL COMMENT '上级ID',
  `home_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '上级名称',
  `group_idx` int NULL DEFAULT NULL COMMENT '组索引',
  `memo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `status` tinyint NULL DEFAULT NULL COMMENT '状态',
  `create_datetime` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `old_id` int NULL DEFAULT NULL COMMENT '旧ID',
  `old_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '旧编码',
  `old_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '旧名称',
  `audit_status` tinyint NULL DEFAULT NULL COMMENT '审核状态（原字段_Status）',
  `audit` tinyint NULL DEFAULT NULL COMMENT '审核标识（原字段_Audit）',
  `auditor` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审核人（原字段_Auditor）',
  `audit_datetime` datetime NULL DEFAULT NULL COMMENT '审核时间（原字段_AuditDatetime）',
  `date` datetime NULL DEFAULT NULL COMMENT '记录日期（原字段_Date）',
  `role` int NULL DEFAULT NULL COMMENT '角色ID（原字段_Role）',
  `data_group` int NULL DEFAULT NULL COMMENT '数据组ID（原字段_DataGroup）',
  `register` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '登记人（原字段_Register）',
  `is_sample` tinyint(1) NULL DEFAULT NULL COMMENT '是否剪板（0否/1是）',
  `is_return` tinyint(1) NULL DEFAULT NULL COMMENT '是否退货',
  `yymmdd` datetime NULL DEFAULT NULL COMMENT '年月日（原字段_YYMMDD）',
  `property_id` int NULL DEFAULT NULL COMMENT '属性ID',
  `property_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '属性名称（成品/胚布/原料等）',
  `is_local` tinyint(1) NULL DEFAULT NULL COMMENT '是否本地',
  `is_quality` tinyint(1) NULL DEFAULT NULL COMMENT '是否质检',
  `is_outsourcing` tinyint(1) NULL DEFAULT NULL COMMENT '是否委外'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '库存组织表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_inventory_transfer_frozen
-- ----------------------------
DROP TABLE IF EXISTS `jf_inventory_transfer_frozen`;
CREATE TABLE `jf_inventory_transfer_frozen`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `inventory_batch_id` bigint NULL DEFAULT NULL COMMENT '库存批次id',
  `inventory_id` bigint NULL DEFAULT NULL COMMENT '库存明细ID',
  `sku` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'sku',
  `order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单号/WMS发起冻结单号',
  `cus_order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客订单号',
  `trader_id` bigint NOT NULL COMMENT '贸易商ID',
  `business_group` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务组别,销售员名称/门市组',
  `inventory_org` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '库存组织',
  `frozen_count` int NOT NULL DEFAULT 0 COMMENT '冻结条数',
  `type` int NULL DEFAULT NULL COMMENT '类型:1=库存调拨,2=货权转移,3=销售寄售，4=销售可用, 5=明细变更减少,6=售后冻结',
  `change_type` int NULL DEFAULT 1 COMMENT '变更类型 1=冻结,2=释放,3=使用',
  `dye_lot_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '缸号',
