  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '贸易商的开票信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_invoice_application
-- ----------------------------
DROP TABLE IF EXISTS `jf_invoice_application`;
CREATE TABLE `jf_invoice_application`  (
  `id` bigint NOT NULL COMMENT '主键 ID',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请单号(开票序列号)',
  `oa_approval_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'OA审批编号',
  `status` int NULL DEFAULT NULL COMMENT '状态（1=草稿，2=待审核，3=审核不通过，4=审核通过，待开票，5=开票成功，6=开票失败，7=冲红中，8=已冲红）',
  `buyer_customer_id` bigint NOT NULL COMMENT '客户id（关联客户表）',
  `buyer_company_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '公司全称/往来单位',
  `buyer_contact_person` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人',
  `buyer_contact_phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系方式',
  `buyer_invoice_id` bigint NULL DEFAULT NULL COMMENT '客户开票信息id',
  `buyer_invoice_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发票抬头',
  `buyer_tax_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '税号',
  `buyer_phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '电话',
  `buyer_bank_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开户银行',
  `buyer_bank_account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '银行账号',
  `buyer_email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '邮箱',
  `buyer_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位地址',
  `buyer_pay_from` int NULL DEFAULT NULL COMMENT '支付方式：1=对公转账，2=动态码付款',
  `buyer_agreement_unit_id` bigint NULL DEFAULT NULL COMMENT '协议单位id(jf_settlement_unit)',
  `buyer_agreement_unit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '协议单位',
  `buyer_has_agreement` tinyint(1) NULL DEFAULT NULL COMMENT '是否有战略协议',
  `buyer_agreement_id` bigint NULL DEFAULT NULL COMMENT '战略协议id',
  `buyer_invoice_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开票资料备注',
  `sales_trader_id` bigint NOT NULL COMMENT '所属贸易商id',
  `sales_trader_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属贸易商',
  `sales_invoice_unit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开票单位',
  `sales_invoice_unit_id` bigint NULL DEFAULT NULL COMMENT '开票单位id(jf_settlement_unit)',
  `sales_tax_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售方税号',
  `sales_bank_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售方开户银行',
  `sales_bank_account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售方银行账号',
  `sales_phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售方电话',
  `sales_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售方单位地址',
  `sales_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售方备注说明',
  `sales_person_in_charge` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '经手人',
  `sales_collection_account` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款账户',
  `collection_account_id` bigint NULL DEFAULT NULL COMMENT '收款账户ID',
  `express_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '快递单号',
  `express_recipient_id` bigint NULL DEFAULT NULL COMMENT '客户收票信息id',
  `express_recipient_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收件人',
  `express_recipient_phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收件电话',
  `express_invoice_email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收票邮箱',
  `express_recipient_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收件地址',
  `express_courier_company` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '快递公司',
  `express_is_prepaid` tinyint(1) NULL DEFAULT 1 COMMENT '是否寄付 1-是 0-否',
  `is_return_form_complete` tinyint(1) NULL DEFAULT NULL COMMENT '是否已填回单 1-是 0-否',
  `invoice_type` int NULL DEFAULT NULL COMMENT '发票类型 (1=普票，2=专票)',
  `invoice_mode` int NULL DEFAULT NULL COMMENT '开票方式（1=已核销开票，2=先开票后付款）',
  `invoice_amount` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '开票金额',
  `invoice_currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'RMB' COMMENT '币种',
  `invoice_currency_rate` decimal(18, 6) NULL DEFAULT NULL COMMENT '币种汇率',
  `invoice_quantity` decimal(16, 2) NULL DEFAULT 1.00 COMMENT '开票数量',
  `invoice_avg_price` decimal(20, 2) NULL DEFAULT 0.00 COMMENT '平均单价',
  `status_desc` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态说明',
  `invoice_total_fee_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT '合计金额',
  `invoice_total_tax_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT '合计税额',
  `invoice_total_amount` decimal(20, 2) NULL DEFAULT NULL COMMENT '价税合计',
  `invoice_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发票代码',
  `invoice_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发票号码',
  `invoice_time` date NULL DEFAULT NULL COMMENT '开票日期',
  `blue_invoice` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '蓝字发票',
  `red_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '红票开票流水号(开票序列号)',
  `red_invoice` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '红字发票',
  `red_info_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '红字发票信息确认单编号',
  `red_info_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '红字发票信息确认单id',
  `red_info_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '红字发票申请时间',
  `is_deducted` tinyint(1) NULL DEFAULT 1 COMMENT '是否已抵扣，1=是，0=否',
  `red_remark` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冲红申请原因',
  `collection_bill_codes` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '已选择收款单号',
  `created_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者 ID/名称',
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者 ID/名称',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态 0-正常 1-删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '发票申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_invoice_application_log
-- ----------------------------
DROP TABLE IF EXISTS `jf_invoice_application_log`;
CREATE TABLE `jf_invoice_application_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键 ID',
  `invoice_application_id` bigint NOT NULL COMMENT '关联申请表 ID (jf_invoice_application.id)',
  `stage_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '阶段类型枚举 (AUDIT (审核结果),ISSUE_SUCCESS (开票成功),ISSUE_FAIL (开票失败),DISPATCH (发出登记),RECOVERY (回收登记),CONFIRM (确认登记),RED_REQUEST (申请冲红),RED_CANCEL (申请作废))',
  `status_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '状态描述/结果文本 (如：审核通过，开票失败)',
  `price_tax_total` decimal(18, 2) NULL DEFAULT NULL COMMENT '价税合计',
  `invoice_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发票代码',
  `invoice_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发票号码',
  `invoice_attachment_url` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发票附件',
  `check_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '校验码',
  `logistics_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物流单号',
  `contract_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '合同编号',
  `identity_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '身份选择',
  `invoice_type` int NULL DEFAULT NULL COMMENT '发票类型 (普票/专票等)',
  `is_deducted` tinyint(1) NULL DEFAULT 1 COMMENT '是否已抵扣，1=是，0=否',
  `red_info_table_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '红字信息表通知编号',
  `operator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人姓名',
  `operate_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '开票日期/操作时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注/原因',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `created_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `updated_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态 0-正常 1-删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_app_id`(`invoice_application_id` ASC) USING BTREE,
  INDEX `idx_stage_time`(`stage_type` ASC, `operate_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3026 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '发票申请状态跟踪日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_invoice_baiwang_async
