  `request` varchar(2550) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '入参',
  `response` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '出参',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '百望发票接口数据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_invoice_fee_detail
-- ----------------------------
DROP TABLE IF EXISTS `jf_invoice_fee_detail`;
CREATE TABLE `jf_invoice_fee_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键 ID',
  `invoice_application_id` bigint NULL DEFAULT NULL COMMENT '发票申请id',
  `fee_item_id` bigint NOT NULL COMMENT '费项池ID',
  `line_no` int NOT NULL COMMENT '行号（百望接口需要）',
  `fee_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '费项类型',
  `fee_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '费项单号',
  `source_order_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源单号',
  `tax_rate` decimal(10, 6) NULL DEFAULT NULL COMMENT '税率',
  `fee_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '费项金额 (含税总额 = feeAmount + taxAmount)',
  `write_off_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '已核销金额 (含税)',
  `un_write_off_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '未核销金额 (含税)',
  `write_off_invoiced_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '核销已开票金额 (元)',
  `review_write_off_invoice_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '待审核核销开票金额(元)',
  `un_write_off_invoiced_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '核销未开票金额 (元)',
  `current_invoiced_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '本次开票金额 (元)',
  `sales_return_quantity` decimal(18, 2) NULL DEFAULT NULL COMMENT '销售/退货数量（kg）',
  `invoiced_quantity` decimal(18, 2) NULL DEFAULT NULL COMMENT '已开票数量（kg）',
  `un_invoiced_quantity` decimal(18, 2) NULL DEFAULT NULL COMMENT '未开票数量（kg）',
  `current_invoiced_quantity` decimal(18, 2) NULL DEFAULT NULL COMMENT '本次开票数量（kg） (逻辑计算字段)',
  `picking_finish_time` datetime NULL DEFAULT NULL COMMENT '发货日期',
  `cut_plate_outbound` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发货仓库',
  `delivery_lifter` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送货抬头',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_fee_code`(`fee_code` ASC) USING BTREE COMMENT '索引：费项单号',
  INDEX `idx_source_order`(`source_order_code` ASC) USING BTREE COMMENT '索引：来源单号'
) ENGINE = InnoDB AUTO_INCREMENT = 2032 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '费项开票明细表' ROW_FORMAT = Dynamic;

