  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `customer_id` bigint NULL DEFAULT NULL COMMENT '客户id',
  `type` int NULL DEFAULT NULL COMMENT '类型（1-标记；2-解除；3-临时解除标记）',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '原因',
  `handle_time` datetime NULL DEFAULT NULL COMMENT '处理时间（如审核通过时间）',
  `related_oa_process_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联OA流程编号（关联合同/审批流程）',
  `temporary_lift_start_time` datetime NULL DEFAULT NULL COMMENT '临时解除开始时间（仅临时类型有效）',
  `temporary_lift_end_time` datetime NULL DEFAULT NULL COMMENT '临时解除结束时间（仅临时类型有效）',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `created_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
