  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 78 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '逾期允许下单标签记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_overdue_rules
-- ----------------------------
DROP TABLE IF EXISTS `jf_overdue_rules`;
CREATE TABLE `jf_overdue_rules`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
