  `overdue_calc_method` int NULL DEFAULT NULL COMMENT '逾期计算方式(1=按单计算，2=按账单计算)',
  `last_payment_limit` int NULL DEFAULT 0 COMMENT '最后付款期限（天-标记期）',
  `overdue_order_duration` int NULL DEFAULT 0 COMMENT '逾期可下单时长（天）',
