  INDEX `idx_transfer_trader`(`transfer_trader_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '货权转移申请' ROW_FORMAT = DYNAMIC;

