  `dyeing_method` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '染色类别',
  `manufacture_technology` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '生产工艺',
  `yarn_shade` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用纱深浅',
  `grey_shade` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用坯深浅',
  `color_shade` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '颜色深浅',
  `sensitive_color` tinyint(1) NOT NULL DEFAULT 0 COMMENT '敏感色',
  `special_sensitive_color` tinyint(1) NOT NULL DEFAULT 0 COMMENT '特敏感色',
