-- ----------------------------
-- Table structure for jf_product
-- ----------------------------
DROP TABLE IF EXISTS `jf_product`;
CREATE TABLE `jf_product`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `record_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备案编码',
  `owner_name` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货主单位',
  `sku` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SKU',
  `goods_id` bigint NULL DEFAULT NULL COMMENT '商品id',
  `spu` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品编号',
  `goods_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品名称',
  `goods_type` int NULL DEFAULT NULL COMMENT '商品类型 1=主身，2=罗纹',
  `ingredient` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成分',
  `dyeing_method_id` bigint NULL DEFAULT NULL COMMENT '染色类别id',
  `finish_width` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '封度',
  `gsm` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '克重',
  `spu_sales_category` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'spu销售类型',
  `sku_sales_category` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'sku销售类型',
  `source_product` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源产品',
  `color_id` bigint NULL DEFAULT NULL COMMENT '色号id',
  `color_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '色号',
  `color_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '颜色',
  `dye_factory_color_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '染厂色号',
  `dye_factory_color_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '染厂颜色名称',
  `replace_color` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '代替颜色',
  `flower_gray_color_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '花灰色号',
  `color_matching_materials` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对色资料',
  `printing_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '打色编码',
  `confirm_color` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认色',
  `cut_meter_price` decimal(20, 4) NULL DEFAULT NULL COMMENT '剪米价',
  `cut_code_price` decimal(20, 4) NULL DEFAULT NULL COMMENT '剪码价',
  `min_sales_price` decimal(20, 4) NULL DEFAULT NULL COMMENT '最低售价',
  `scattered_unit_price` decimal(20, 4) NULL DEFAULT NULL COMMENT '散剪单价',
  `latest_sales_price` decimal(20, 4) NULL DEFAULT NULL COMMENT '最新销售价 (毛重)',
  `net_weight_coefficient` decimal(5, 2) NULL DEFAULT 1.00 COMMENT '净重系数',
  `net_weight_unit_price` decimal(20, 6) NULL DEFAULT NULL COMMENT '净重单价',
  `net_weight_tax_inclusive_price` decimal(20, 6) NULL DEFAULT NULL COMMENT '净重含税价',
  `color_adjustment_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '颜色调价',
  `activity_adjustment_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '活动调价',
  `special_sensitive_color` decimal(10, 2) NULL DEFAULT NULL COMMENT '特敏感',
  `anti_fluorescent` decimal(10, 2) NULL DEFAULT NULL COMMENT '防荧光',
  `tax_inclusive_price` decimal(20, 6) NULL DEFAULT NULL COMMENT '含税价',
  `pricing_unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计价单位',
  `price_remarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '价格说明',
  `items_per_tube` int NULL DEFAULT 12 COMMENT '每管条数',
  `suspend_time` datetime NULL DEFAULT NULL COMMENT '下架时间',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态：1:启用，0:停用',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除',
  `build_time` datetime NULL DEFAULT NULL COMMENT '建档时间',
  `record_date` date NULL DEFAULT NULL COMMENT '备案时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sku`(`sku` ASC) USING BTREE,
  INDEX `idx_spu`(`spu` ASC) USING BTREE,
  INDEX `idx_goods`(`goods_id` ASC) USING BTREE,
  INDEX `idx_printing`(`printing_code` ASC) USING BTREE,
  INDEX `idx_product_sku`(`sku` ASC) USING BTREE,
  INDEX `idx_product_goodsname`(`goods_name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 354340 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '产品颜色' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_product_attribute
-- ----------------------------
DROP TABLE IF EXISTS `jf_product_attribute`;
CREATE TABLE `jf_product_attribute`  (
  `id` bigint NOT NULL COMMENT '主键',
