  `net_weight_unit_price` decimal(20, 2) NULL DEFAULT NULL COMMENT '净重单价',
  `net_weight_tax_inclusive_price` decimal(20, 2) NULL DEFAULT NULL COMMENT '净重含税价',
  `color_adjustment_price` decimal(20, 2) NULL DEFAULT NULL COMMENT '颜色调价',
  `activity_adjustment_price` decimal(20, 2) NULL DEFAULT NULL COMMENT '活动调价',
  `special_sensitive_color` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否特敏感色',
  `anti_fluorescent` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否防荧光处理',
  `tax_inclusive_price` decimal(20, 2) NULL DEFAULT NULL COMMENT '含税价',
