  `quotation_writer` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '报价人',
  `quotation_time` date NULL DEFAULT NULL COMMENT '报价时间',
  `validity_period` datetime NULL DEFAULT NULL COMMENT '报价有效期',
  `calculating_price_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '计价单号',
  `order_color_fabric_unit_on_off` tinyint NULL DEFAULT NULL COMMENT '订单色布均价多选框',
  `order_white_fabric_unit_on_off` tinyint NULL DEFAULT NULL COMMENT '订单白布均价多选框',
  `province` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '省',
  `city` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '市',
  `area` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '区',
  `street` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '街道',
  `customer` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '客户',
  `delete_status` tinyint NOT NULL DEFAULT 0 COMMENT '删除状态',
  `customer_id` bigint NULL DEFAULT NULL COMMENT '客户id',
  `is_send_mail` tinyint(1) NULL DEFAULT 0 COMMENT '是否已发送站内信',
  `version` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '版本号（用于生成唯一单号）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '立项分析\r\n' ROW_FORMAT = Dynamic;

