-- ----------------------------
-- Table structure for jf_quality_compensation
-- ----------------------------
DROP TABLE IF EXISTS `jf_quality_compensation`;
CREATE TABLE `jf_quality_compensation`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
