  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_product`(`spu` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 67 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '质量补损信息表' ROW_FORMAT = DYNAMIC;

