  `order_white_fabric_unit` decimal(10, 2) NULL DEFAULT NULL COMMENT '订单白布均价',
  `single_color_quote` int NULL DEFAULT NULL COMMENT '单色报价(1:是 2：否)',
  `price_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '计价备注',
  `quotation_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '计价单号',
  `order_color_fabric_unit_on_off` tinyint(1) NULL DEFAULT NULL COMMENT '订单色布均价多选框',
  `order_white_fabric_unit_on_off` tinyint(1) NULL DEFAULT NULL COMMENT '订单白布均价多选框',
  `quoter` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '报价人',
  `quote_time` datetime NULL DEFAULT NULL COMMENT '报价时间',
  `quote_status` int NULL DEFAULT 1 COMMENT '报价状态：1：待报价；2：已报价；3：报价已过期',
  `quote_validity` datetime NULL DEFAULT NULL COMMENT '报价有效期',
  `quotation_application_id` bigint NULL DEFAULT NULL COMMENT '报价申请id',
  `goods_id` bigint NULL DEFAULT NULL COMMENT '商品id',
  `is_send_mail` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已发送站内信',
  `color_id` int NULL DEFAULT NULL COMMENT '色号id',
  `fabric_id` int NULL DEFAULT NULL COMMENT '布品id',
  `spec` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格id',
  `goods_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '布号',
  `quota_id` int NULL DEFAULT NULL COMMENT '报价申请id'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

