-- ----------------------------
-- Table structure for jf_rebate
-- ----------------------------
DROP TABLE IF EXISTS `jf_rebate`;
CREATE TABLE `jf_rebate`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `customer_id` bigint NULL DEFAULT NULL COMMENT '客户id',
  `customer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户编码',
  `rebate_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结算返利单号',
  `settlement_start_time` datetime NULL DEFAULT NULL COMMENT '开始结算时间',
  `settlement_end_time` datetime NULL DEFAULT NULL COMMENT '结束结算时间',
  `trader_short_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属贸易商',
  `discount_method` int NULL DEFAULT NULL COMMENT '下单优惠方式',
  `strategic_agreement` tinyint NULL DEFAULT NULL COMMENT '是否签署战略协议',
  `strategic_agreement_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '战略协议备案编号',
  `agreement_start_time` date NULL DEFAULT NULL COMMENT '协议开始时间',
  `agreement_end_time` date NULL DEFAULT NULL COMMENT '协议结束时间',
  `customer_short_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户简称',
  `company` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '公司全称(客户名称)',
  `business_manager` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务经理',
  `store_sales` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '门店销售',
  `brand_name` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品牌系列',
  `brand_parent` tinyint(1) NULL DEFAULT 0 COMMENT '品牌父级',
  `customer_base` tinyint(1) NULL DEFAULT 0 COMMENT '客户主体',
  `control_account_period` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结算方式(账期管理)',
  `type` int NULL DEFAULT NULL COMMENT '类别 1:直接客户  2：内部客户',
  `current_customer_level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当前客户等级',
  `current_level_id` bigint NULL DEFAULT NULL COMMENT '当前等级条件id',
  `current_level_name` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当前等级条件',
  `current_level_min_sales_tonnage` int NULL DEFAULT NULL COMMENT '当前等级条件最小销售吨数',
  `current_level_max_sales_tonnage` int NULL DEFAULT NULL COMMENT '当前等级条件最大销售吨数',
  `current_level_discount_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '当前等级优惠单价',
  `total_sales_tonnage` decimal(10, 2) NULL DEFAULT NULL COMMENT '累计销售重量(KG)',
  `total_return_tonnage` decimal(10, 2) NULL DEFAULT NULL COMMENT '累计退货重量(KG)',
  `actual_sales_tonnage` decimal(10, 2) NULL DEFAULT NULL COMMENT '实际销售重量(KG)',
  `updated_customer_level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新后客户等级',
  `updated_level_id` bigint NULL DEFAULT NULL COMMENT '更新后等级条件id',
  `updated_level_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新后等级条件',
  `updated_level_min_sales_tonnage` int NULL DEFAULT NULL COMMENT '更新后等级条件最小销售吨数',
  `updated_level_max_sales_tonnage` int NULL DEFAULT NULL COMMENT '更新后等级条件最大销售吨数',
  `updated_level_discount_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '更新后等级优惠单价',
  `total_sales_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '累计销售金额',
  `total_refund_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '累计退款金额',
  `actual_sales_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '累计实际销售金额（= 累计销售金额 - 累计退款金额）',
  `updated_level_sales_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '累计更新等级后销售金额',
  `rebate_difference` decimal(12, 2) NULL DEFAULT NULL COMMENT '返利差额',
  `final_confirmed_rebate_difference` decimal(12, 2) NULL DEFAULT NULL COMMENT '最终确认返利差额',
  `audit_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `audit_status` int NOT NULL DEFAULT 1 COMMENT '返利审核状态：1=待财务确认，2=待业务确认，3=业务审核通过',
  `created_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改人',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态（FALSE：未删除，TRUE：已删除）',
  `trader_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '贸易商',
  `confirm_person` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认人',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认时间',
  `is_triggered` tinyint(1) NULL DEFAULT 0 COMMENT '是否触发返利（非战略客户一月一日，战略客户协议到期）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '年底返利结算表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_rebate_audit_log
-- ----------------------------
DROP TABLE IF EXISTS `jf_rebate_audit_log`;
CREATE TABLE `jf_rebate_audit_log`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `rebate_id` bigint NOT NULL COMMENT '返利结算id',
  `audit_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `audit_status` int NOT NULL DEFAULT 1 COMMENT '返利审核状态：1=待财务确认，2=待业务确认，3=业务审核通过',
  `created_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改人',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态（FALSE：未删除，TRUE：已删除）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '年底返利结算审核记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_rebate_detail
-- ----------------------------
DROP TABLE IF EXISTS `jf_rebate_detail`;
CREATE TABLE `jf_rebate_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `rebate_id` bigint NULL DEFAULT NULL COMMENT '年底返利ID',
  `rebate_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '年底返利单号',
  `type` int NULL DEFAULT NULL COMMENT '类型：1=本期销售并且本期退货/无退货，2=本期退货但销售不在本期',
  `sales_order_id` bigint NULL DEFAULT NULL COMMENT '销售单ID',
  `sales_order_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售单编码',
  `customer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户编码',
  `customer_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户全称',
  `sales_order_status` int NULL DEFAULT NULL COMMENT '销售单状态：SalesOrdersStatus',
  `shipments_status` int NULL DEFAULT NULL COMMENT '发货状态：ShipmentsStatus',
  `payment_status` int NULL DEFAULT NULL COMMENT '付款状态：PaymentStatus',
  `sales_order_detail_id` bigint NULL DEFAULT NULL COMMENT '销售单明细ID',
  `sales_order_type` int NULL DEFAULT NULL COMMENT '销售类型：SalesOrderDetailType',
  `spu` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SPU',
  `goods_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品编号',
  `goods_type` int NULL DEFAULT NULL COMMENT '商品类型：GoodsTypeEnum',
  `sku` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SKU',
  `color_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '色号',
  `color_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '色称',
  `quantity` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '购买数量',
  `sales_unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售单位',
  `sales_weight` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '销售重量',
  `base_price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '标准单价',
  `discount_price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '优惠单价',
  `post_discount_price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '优惠后单价',
  `sales_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '销售金额',
  `return_order_code_list` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退货销售单列表',
  `return_weight` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '退货重量',
  `return_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '退货金额',
  `actual_weight` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '实际重量',
  `actual_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '实际金额',
  `level_update_discount_price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '更新等级优惠单价',
  `post_level_update_discount_price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '更新等级后优惠单价',
  `post_level_update_sales_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '更新等级后销售金额',
  `expected_rebate_difference` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '预计返利差额',
  `rebated_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '已返利金额',
  `un_rebated_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '未返利金额',
  `final_confirmed_rebate_difference` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '最终确认返利差额',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sales_order_id`(`sales_order_id` ASC) USING BTREE,
  INDEX `idx_sales_order_detail_id`(`sales_order_detail_id` ASC) USING BTREE,
  INDEX `idx_sales_order_code`(`sales_order_code` ASC) USING BTREE,
  INDEX `idx_customer_status_type`(`customer_code` ASC, `sales_order_status` ASC, `type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 249 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '返利商品明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_rebate_query_temp
-- ----------------------------
DROP TABLE IF EXISTS `jf_rebate_query_temp`;
CREATE TABLE `jf_rebate_query_temp`  (
  `id` bigint NOT NULL COMMENT '主键',
  `rebate_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '年度返利结算单号',
  `customer_id` bigint NULL DEFAULT NULL COMMENT '客户id',
  `start_time` datetime NULL DEFAULT NULL COMMENT '结算开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结算结束时间',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态',
  `cache_status` tinyint(1) NULL DEFAULT NULL COMMENT '是否缓存',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_customer_id`(`customer_id` ASC) USING BTREE COMMENT '客户id索引，优化查询',
  INDEX `idx_rebate_code`(`rebate_code` ASC) USING BTREE COMMENT '年度返利结算单号'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '年度返利结算--客户信息（临时表）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_receipt_account_match
-- ----------------------------
DROP TABLE IF EXISTS `jf_receipt_account_match`;
CREATE TABLE `jf_receipt_account_match`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '匹配编号',
  `trader_id` bigint NOT NULL COMMENT '贸易商ID',
  `business_group` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务组别,销售员名称/门市组',
  `pay_form` int NOT NULL COMMENT '支付方式（1=对公转账，2=动态码付款）',
  `collection_account_id` bigint NOT NULL COMMENT '收款账号ID',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 (0:禁用, 1:启用)',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  `pay_form_id` bigint NOT NULL COMMENT '支付形式ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_collection_account`(`collection_account_id` ASC) USING BTREE,
  INDEX `idx_trader`(`trader_id` ASC) USING BTREE,
  INDEX `idx_pay_method`(`pay_form` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3024 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '收款账户匹配' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_receipt_information
-- ----------------------------
DROP TABLE IF EXISTS `jf_receipt_information`;
CREATE TABLE `jf_receipt_information`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `recipient` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '收件人',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联系电话',
  `recipient_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '收件地址',
  `receive_invoices_email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收发票邮箱',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `customer_id` bigint NOT NULL COMMENT '客户id（关联客户表）',
  `created_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人',
  `created_time` datetime NOT NULL COMMENT '创建时间',
  `updated_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修改人',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除状态',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '收票信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_receivable_claim
-- ----------------------------
DROP TABLE IF EXISTS `jf_receivable_claim`;
CREATE TABLE `jf_receivable_claim`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '应收认领单号',
  `type` int NULL DEFAULT 0 COMMENT '单据类型:0=应收, 1=客订订金，2=预付款',
  `customer_id` bigint NOT NULL COMMENT '客户id',
  `customer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户编号',
  `customer_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户名称',
  `contacts_id` bigint NULL DEFAULT NULL COMMENT '联系人id',
  `consignee` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收货人',
  `contact_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '联系电话',
  `trader_short_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '贸易商简称',
  `business_group` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务组别',
  `business_manager` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务经理',
  `store_sales` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '门店销售',
  `collection_notice_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款通知单号(链接编码)',
  `payment_method` int NOT NULL COMMENT '支付方式：1=对公转账,2=动态码付款',
  `control_account_period_id` bigint NOT NULL COMMENT '账期id',
  `control_account_period` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '账期',
  `status` int NOT NULL DEFAULT 1 COMMENT '状态，1=待审核；2=已审核；3=审核不通过',
  `settlement_org` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '核算组织',
  `collection_account_id` bigint NOT NULL COMMENT '收款账户ID',
  `accounts_time` date NULL DEFAULT NULL COMMENT '收款日期',
  `open_account_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款账户',
  `open_account` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款账号',
  `income_bill_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '进账单号',
  `income_customer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '进账客户编码',
  `write_off_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '核销金额',
  `currency_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '币种代码',
  `currency_rate` decimal(10, 6) NULL DEFAULT NULL COMMENT '币种汇率',
  `invoice_type` int NOT NULL DEFAULT 0 COMMENT '开票类型：0=不开票，1=普票，2=专票',
  `tax_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '税率',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注说明',
  `import_account_balance` decimal(18, 2) NULL DEFAULT NULL COMMENT '汇入账户余额',
  `adjustment_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '优惠调价金额',
  `adjustment_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '优惠调价单号',
  `match_count` int NULL DEFAULT NULL COMMENT '匹配次数',
  `remitter` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '汇款人',
  `audit_opinion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核意见',
  `audit_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uq_code`(`code` ASC) USING BTREE,
  INDEX `idx_customer`(`customer_id` ASC) USING BTREE,
  INDEX `idx_contacts`(`contacts_id` ASC) USING BTREE,
  INDEX `idx_collection_account`(`collection_notice_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 486 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '应收认领单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_receivable_claim_fee_item
-- ----------------------------
DROP TABLE IF EXISTS `jf_receivable_claim_fee_item`;
CREATE TABLE `jf_receivable_claim_fee_item`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `receivable_claim_id` bigint NOT NULL COMMENT '应收认领单ID',
  `fee_item_id` bigint NOT NULL COMMENT '费项汇总ID',
  `fee_item_type` int NULL DEFAULT NULL COMMENT '费项类型（1=费项，2=税费）',
  `write_off_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '已核销金额',
  `current_write_off_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '本次核销金额',
  `discount_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '优惠金额',
  `un_write_off_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '未核销金额(应收-本次核销)',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  `due_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '应收金额(费项金额-已核销)-提交时的快照',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_receivable_claim`(`receivable_claim_id` ASC) USING BTREE,
  INDEX `idx_fee_item`(`fee_item_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 599 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '应收认领单费用项目' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_receivable_claim_fee_item_audit_log
-- ----------------------------
DROP TABLE IF EXISTS `jf_receivable_claim_fee_item_audit_log`;
CREATE TABLE `jf_receivable_claim_fee_item_audit_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `source_doc_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源单据类型(RECEIVABLE_CLAIM=应收认领单,COLLECTION_NOTICE=收款通知单,WRITE_OFF=核销单)',
  `source_doc_id` bigint NOT NULL COMMENT '来源单据ID',
  `source_doc_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源单据编号',
  `fee_item_type` tinyint NOT NULL COMMENT '费项类型(1=费项,2=税费)',
  `fee_item_id` bigint NOT NULL COMMENT '费项ID(jf_fee_item.ID)',
  `fee_item_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '费项编号',
  `before_amount` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '变更前核销金额',
  `change_amount` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '本次核销变更金额',
  `after_amount` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '变更后核销金额',
  `operator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '操作人',
  `operated_time` datetime NOT NULL COMMENT '操作时间',
  `created_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_source_doc`(`source_doc_type` ASC, `source_doc_id` ASC) USING BTREE,
  INDEX `idx_fee_item_id`(`fee_item_id` ASC) USING BTREE,
  INDEX `idx_operated_time`(`operated_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 56 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '费项核销审核流水日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_receivable_claim_quota_recovery_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_receivable_claim_quota_recovery_record`;
CREATE TABLE `jf_receivable_claim_quota_recovery_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `receivable_claim_id` bigint NOT NULL COMMENT '应收认领单ID',
  `sales_order_id` bigint NOT NULL COMMENT '销售单ID',
  `sales_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '销售单号',
  `sales_order_quota_usage_record_id` bigint NOT NULL COMMENT '销售单额度使用来源记录ID',
  `contract_quota_id` bigint NULL DEFAULT NULL COMMENT '合同自有额度ID',
  `allocation_quota_id` bigint NULL DEFAULT NULL COMMENT '分配额度ID',
  `is_using_own` tinyint(1) NOT NULL COMMENT '是否使用合同自有额度',
  `recovery_amount` decimal(19, 2) NOT NULL COMMENT '本次恢复金额',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `created_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新人',
  `updated_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除标识',
  `version_no` int NULL DEFAULT NULL COMMENT '版本号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_claim_usage_record`(`receivable_claim_id` ASC, `sales_order_quota_usage_record_id` ASC) USING BTREE,
  INDEX `idx_sales_order_id`(`sales_order_id` ASC) USING BTREE,
  INDEX `idx_usage_record_id`(`sales_order_quota_usage_record_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '应收认领审核额度恢复明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_receivable_refund_order
-- ----------------------------
DROP TABLE IF EXISTS `jf_receivable_refund_order`;
CREATE TABLE `jf_receivable_refund_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `refund_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '退款单号',
  `refund_date` date NULL DEFAULT NULL COMMENT '退款日期',
  `refund_category_id` bigint NOT NULL COMMENT '退款单据类别ID(费项管理)',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
  `trader_id` bigint NULL DEFAULT NULL COMMENT '用户贸易商ID',
  `refund_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `currency_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '交易币种code',
  `currency_rate` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '币种汇率',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注说明',
  `audit_opinion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核意见',
  `audit_status` int NOT NULL DEFAULT 1 COMMENT '状态 (1:待审核, 2:审核通过, 3:审核不通过)',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  `review` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `review_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `pay_method` int NULL DEFAULT NULL COMMENT '退款（付款）方式（1：现金；2：转账；3：支付宝；4：微信）',
  `return_account` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退款账号',
  `customer_trader_short_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户贸易商',
  `customer_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户名称（往来单位）',
  `company` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '公司（单位全称）',
  `contacts_id` bigint NULL DEFAULT NULL COMMENT '联系人',
  `consignee` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收货人',
  `contact_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `trader_short_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '贸易商简称',
  `business_group` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务组别',
  `business_manager` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务经理',
  `store_sales` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '门店销售',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_jf_receivable_refund_order_refund_code`(`refund_code` ASC) USING BTREE,
  INDEX `idx_refund_category`(`refund_category_id` ASC) USING BTREE,
  INDEX `idx_customer`(`customer_id` ASC) USING BTREE,
  INDEX `idx_trader`(`trader_id` ASC) USING BTREE,
  INDEX `idx_currency`(`currency_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '应收退款单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_receivable_refund_order_detail
-- ----------------------------
DROP TABLE IF EXISTS `jf_receivable_refund_order_detail`;
CREATE TABLE `jf_receivable_refund_order_detail`  (
