  `fee_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '费项单号',
  `fee_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '费项金额',
  `write_off_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '核销金额',
