  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_receivable_refund_order`(`receivable_refund_order_id` ASC) USING BTREE,
  INDEX `idx_sales_order`(`fee_item_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '应收退款单表明细' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_receivable_write_off
-- ----------------------------
DROP TABLE IF EXISTS `jf_receivable_write_off`;
CREATE TABLE `jf_receivable_write_off`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `write_off_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '核销单号',
  `write_off_time` datetime NULL DEFAULT NULL COMMENT '核销时间',
  `write_off_date` date NULL DEFAULT NULL COMMENT '核销日期',
  `write_off_type` int NOT NULL DEFAULT 1 COMMENT '单据类型 (1=应收核销单, 2=订金核销单, 3=其他核销单)',
  `total_write_off_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '总核销金额',
  `dept_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属组织',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注说明',
  `customer_id` bigint NOT NULL COMMENT '客户ID',
