-- ----------------------------
-- Table structure for jf_reservation_stock_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_reservation_stock_record`;
CREATE TABLE `jf_reservation_stock_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `reservation_stock_id` bigint NOT NULL COMMENT '关联的客订备货ID（jf_reservation_stock.id）',
  `order_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客订备货单号',
  `change_type` int NOT NULL COMMENT '变动类型：1=冻结；2=释放；3=使用',
  `change_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '本次变动金额',
  `pre_frozen` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '变动前冻结订金',
  `post_frozen` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '变动后冻结订金',
  `pre_used` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '变动前已用订金',
  `post_used` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '变动后已用订金',
  `related_business_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联业务单据号（销售单号）',
  `operate_people` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作人',
  `operate_time` datetime NOT NULL COMMENT '操作时间',
  `change_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '变动原因',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建者',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除：0=否；1=是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_reservation_stock_record_stock_id`(`reservation_stock_id` ASC, `delete_status` ASC) USING BTREE,
  INDEX `idx_reservation_stock_record_order_code`(`order_code` ASC, `delete_status` ASC) USING BTREE,
  INDEX `idx_reservation_stock_record_business_code`(`related_business_code` ASC, `delete_status` ASC) USING BTREE,
  INDEX `idx_reservation_stock_record_operate_time`(`operate_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '客订备货订金资金变动流水表' ROW_FORMAT = Dynamic;

