CREATE TABLE `jf_return_frozen_sn_details`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `inventory_batch_id` bigint NULL DEFAULT NULL COMMENT '库存批次id',
  `inventory_id` bigint NULL DEFAULT NULL COMMENT '库存明细ID',
  `order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单号',
  `sku` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'sku',
  `sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冻结细码',
  `change_type` int NULL DEFAULT 1 COMMENT '变更类型 1=冻结,2=释放为可用,3=扣除',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_inventory`(`inventory_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 118 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '退货细码库存冻结明细(细码维度)' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_return_product
-- ----------------------------
DROP TABLE IF EXISTS `jf_return_product`;
CREATE TABLE `jf_return_product`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_type` int NOT NULL COMMENT '单据类型: 1=拦截退, 2=退货',
  `request_order_id` bigint NULL DEFAULT NULL COMMENT '销售退货申请单id',
  `request_order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '销售退货申请单号',
  `return_order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售退货单号',
  `sales_product_id` bigint NOT NULL COMMENT '销售单关联产品/细码id',
  `dye_lot_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产缸号',
  `fixed_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '疋号',
  `sku` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'sku',
  `product_type` int NULL DEFAULT NULL COMMENT '类型（1=大货，2=剪板）',
  `sn_status` int NULL DEFAULT 1 COMMENT '细码质检状态: 1=待收货、2=无需质检、3=待质检、4=质检完成、5=收货异常、6=质检异常',
  `qty` int NULL DEFAULT 1 COMMENT '条数/申请条数',
  `refundable_qty` int NULL DEFAULT NULL COMMENT '可退条数',
  `sn_weight` decimal(10, 1) NULL DEFAULT NULL COMMENT '细码重量',
  `meters` decimal(10, 2) NULL DEFAULT NULL COMMENT '米数(拦截退)',
  `wash_yards` decimal(10, 2) NULL DEFAULT NULL COMMENT '码数(拦截退)',
  `roll_line_discount` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '驳口优惠(商品优惠总金额)',
  `discount_strategy` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '优惠策略, 多个;分割',
  `sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成品细码',
  `another_one_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常情况1时, 另一条细码',
  `another_one_sn_weight` decimal(10, 1) NULL DEFAULT NULL COMMENT '异常情况1时, 另一条细码重量',
  `original_sales_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '原销售单价',
  `return_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '退货单价',
  `abnormal_cause` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常原因',
  `measure_weight` decimal(10, 1) NULL DEFAULT NULL COMMENT '计量重量',
  `difference_weight` decimal(10, 1) NULL DEFAULT NULL COMMENT '差异重量',
  `return_qty` decimal(10, 1) NULL DEFAULT NULL COMMENT '退货数量',
  `return_pre_length` decimal(10, 1) NULL DEFAULT NULL COMMENT '退货米数',
  `pre_length` decimal(10, 2) NULL DEFAULT NULL COMMENT '洗前出米数',
  `discounted_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '折扣单价',
  `adj_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '调整单价',
  `expected_refund` decimal(10, 2) NULL DEFAULT NULL COMMENT '预计退款',
  `actual_refund` decimal(10, 2) NULL DEFAULT NULL COMMENT '实际退款',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `abnormal_type` int NULL DEFAULT NULL COMMENT '异常情况: 1. 细码不是退货单中的, 是原销售单的, 2. 细码不是退货单选的, 也不是销售单的, 3. 回来某条细码对色情况为不对色, 4=仓库收货缺少该细码',
  `ware_house_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '逻辑仓',
  `spu_sales_category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'spu销售类型',
  `sku_sales_category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'sku销售类型',
  `net_weight_return_qty` decimal(10, 1) NULL DEFAULT NULL COMMENT '退货净重数量',
  `tax_excluded_unitPrice` decimal(10, 2) NULL DEFAULT NULL COMMENT '不含税单价',
  `unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'KG' COMMENT '单位',
  `is_unfreeze` tinyint NULL DEFAULT NULL COMMENT '是否解冻过',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=已删除，0=未删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sales_return_request`(`request_order_code` ASC) USING BTREE,
  INDEX `idx_return_product_order_delete`(`return_order_code` ASC, `delete_status` ASC, `abnormal_type` ASC, `sales_product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 845 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售退货申请产品信息' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_return_quality_result
-- ----------------------------
DROP TABLE IF EXISTS `jf_return_quality_result`;
CREATE TABLE `jf_return_quality_result`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `return_order_id` bigint NOT NULL COMMENT '退货单ID',
  `return_order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '退货单号',
  `sku` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'sku',
  `actual_fixed_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实际疋号',
  `fixed_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请疋号',
  `actual_product_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实际细码',
  `product_sn` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请细码',
  `cm_project` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '加工项',
  `color_situation` tinyint NULL DEFAULT NULL COMMENT '对色情况',
  `gross_weight` decimal(10, 1) NULL DEFAULT NULL COMMENT '毛重',
  `net_weight` decimal(10, 1) NULL DEFAULT NULL COMMENT '净重',
  `quality_status` tinyint NULL DEFAULT NULL COMMENT '是否合格',
  `responsibility` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '责任判定结论',
  `repair_order_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '加工回修单号',
  `inbound_sn_id` bigint NULL DEFAULT NULL COMMENT '关联入库细码表id',
  `judge_results` int NULL DEFAULT NULL COMMENT '判定结果: 0=质检没问题, 1=仓库加工,  2=质量问题发染厂加工, 3=客户问题发染厂加工',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=已删除，0=未删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sales_return_request`(`return_order_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 45 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '质检结果' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_return_repair_dye
-- ----------------------------
DROP TABLE IF EXISTS `jf_return_repair_dye`;
CREATE TABLE `jf_return_repair_dye`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `repair_order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '加工回修单号',
  `dye_lot_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产缸号',
  `original_spu_id` bigint NULL DEFAULT NULL COMMENT '原商品id',
  `original_spu` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原商品编号',
  `original_color_id` bigint NULL DEFAULT NULL COMMENT '原色号id',
  `original_color_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原色号',
  `processing_color` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '加工颜色',
  `spu_id` bigint NULL DEFAULT NULL COMMENT '商品id',
  `spu` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品编号',
  `sku` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'sku',
  `color_id` bigint NULL DEFAULT NULL COMMENT '色号id',
  `color_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '色号',
  `color_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '颜色',
  `finished_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成品名称',
  `goods_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品名称',
  `dye_factory_color` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '染厂色号',
  `color_matching_data` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对色资料',
  `is_into_bath` tinyint(1) NULL DEFAULT 0 COMMENT '进缸，0=否，1=是',
  `is_repack` tinyint(1) NULL DEFAULT 0 COMMENT '重打包，0=否，1=是',
  `dye_type` int NULL DEFAULT NULL COMMENT '合染类型: 1=合染收小缸费、2=合染不收小缸费',
  `production_process` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产工艺(加工项)',
  `loss_rate` int NULL DEFAULT 3 COMMENT '损耗率',
  `qty` int NULL DEFAULT NULL COMMENT '条数',
  `fallen_weight` decimal(10, 1) NULL DEFAULT NULL COMMENT '落坯重',
  `finished_weight` decimal(10, 1) NULL DEFAULT NULL COMMENT '成品重',
  `processing_rate` decimal(10, 2) NULL DEFAULT NULL COMMENT '加工单价',
  `piece_rate` decimal(10, 2) NULL DEFAULT NULL COMMENT '计件单价',
  `return_loss_fee` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '返定损耗费，如：2.00',
  `additional_fee` decimal(10, 2) NULL DEFAULT NULL COMMENT '附加费，请填写',
  `total_amount` decimal(14, 2) NULL DEFAULT NULL COMMENT '合计金额',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `is_oa` tinyint NULL DEFAULT NULL COMMENT '发OA生控报价: 0=待发起, 1=已发起',
  `total_sales_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '总销售单价(合计原销售单价)',
  `ware_house_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '逻辑仓',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=已删除，0=未删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_return_repair_order`(`repair_order_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 28 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '加工回修单-缸号' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_return_repair_order
-- ----------------------------
DROP TABLE IF EXISTS `jf_return_repair_order`;
CREATE TABLE `jf_return_repair_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `repair_order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '加工回修单号',
  `status` int NULL DEFAULT 1 COMMENT '状态：1=待确认，2=回修中，3=回修入库',
  `return_order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退货单号',
  `settlement_unit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '超俊针织' COMMENT '结算单位',
  `repair_type` int NULL DEFAULT NULL COMMENT '回修类型: 1=成品加工，2=退货回修，3=内部回修',
  `cost_bearer` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '费用承担',
  `processor` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '粤隆染厂' COMMENT '加工商',
  `urgency_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '一般' COMMENT '紧急状态',
  `qb_date` date NULL DEFAULT NULL COMMENT '齐坯日期',
  `request_date` date NULL DEFAULT NULL COMMENT '要求日期',
  `quality_standard` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '一般' COMMENT '质量标准',
  `quality_standard_id` bigint NULL DEFAULT NULL COMMENT '质量标准id',
  `receiving_unit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '粤隆染厂' COMMENT '收货单位',
  `repair_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '回修原因',
  `confirm_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认人',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `picking_order_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '拣货单号(内部回修单用)',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=已删除，0=未删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '加工回修单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_return_repair_packaging
-- ----------------------------
DROP TABLE IF EXISTS `jf_return_repair_packaging`;
CREATE TABLE `jf_return_repair_packaging`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `repair_order_id` bigint NULL DEFAULT NULL COMMENT '加工回修单ID',
  `net_gross_weight_rule` int NULL DEFAULT NULL COMMENT '净重/毛重规则: 1=以毛重出货、2=以净重出货',
  `packaging_carton_id` bigint NULL DEFAULT NULL COMMENT '包装纸筒id',
  `packaging_carton` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '包装纸筒',
  `carton_weight` decimal(5, 1) NULL DEFAULT NULL COMMENT '纸筒重量',
  `packaging_bag_id` bigint NULL DEFAULT NULL COMMENT '包装胶袋id',
  `packaging_bag` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '包装胶袋',
  `bag_weight` decimal(5, 1) NULL DEFAULT NULL COMMENT '胶袋重量',
  `added_empty_weight` decimal(5, 1) NULL DEFAULT NULL COMMENT '加空重量',
  `tag_label_rule` int NULL DEFAULT 2 COMMENT '码卡标签: 1=常用净重、2=本厂重量、3=浚丰标签、4=YF净重、5=常用毛重、6=常用毛净重、7=本厂净重、8=常用毛净重含米数、9=台巨标签、10=品牌部中文、11=品牌部英文、12=金士达标签、13=中英文标签、14=金瑞纺织标签',
  `delivery_format` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送货格式',
  `delivery_headline` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送货抬头',
  `packaging_remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '包装说明',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=已删除，0=未删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_return_repair_order`(`repair_order_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 63 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '加工回修单包装要求表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_return_repair_quality
-- ----------------------------
DROP TABLE IF EXISTS `jf_return_repair_quality`;
CREATE TABLE `jf_return_repair_quality`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
