  `value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '值',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=已删除，0=未删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_return_repair_order`(`repair_order_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 159 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '加工回修单质量要求' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_role_trader_mapping
-- ----------------------------
DROP TABLE IF EXISTS `jf_role_trader_mapping`;
CREATE TABLE `jf_role_trader_mapping`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `created_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间，为空则数据库自动设置当前时间',
  `updated_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间，为空则数据库自动设置当前时间',
  `created_by` bigint NULL DEFAULT NULL COMMENT '创建者',
  `updated_by` bigint NULL DEFAULT NULL COMMENT '更新者',
  `role_id` bigint NULL DEFAULT NULL COMMENT '角色id',
  `trader_id` bigint NOT NULL COMMENT '贸易商id',
  `delete_status` tinyint NOT NULL DEFAULT 0 COMMENT '状态(1删除 0正常)',
  `abbreviation` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '贸易商简称',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `key_role_id`(`role_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 156 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '角色与贸易商绑定关系' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_sales_category
-- ----------------------------
DROP TABLE IF EXISTS `jf_sales_category`;
CREATE TABLE `jf_sales_category`  (
  `id` bigint NOT NULL COMMENT '主键',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新者',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '销售类别',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '销售类别' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_sales_order
-- ----------------------------
DROP TABLE IF EXISTS `jf_sales_order`;
CREATE TABLE `jf_sales_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '销售单编码',
  `status` int NOT NULL DEFAULT 0 COMMENT '单据状态：1=草稿，2=已取消，3=OA审核中，4=0A审核不通过，5=库存不足，6=锁缸结果待确认，7=对色回传中，8=对色结果待确认，9=已锁缸，10=已派单，11=拣货中，12=已出数，13=待发进仓，14=派车，15=待发出仓，16=付运,17=送达,-99=异常,-98=下单中',
  `payment_status` int NOT NULL DEFAULT 1 COMMENT '收款状态：0=作废，1=未收款，2=部分收款，3=已收款(由定时任务更新)',
  `customer_id` bigint NOT NULL COMMENT '客户id',
  `customer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户编号',
  `customer_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户名称',
  `store_sales` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '门店销售',
  `business_manager` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务经理',
  `trader_id` bigint NOT NULL COMMENT '贸易商id',
  `trader_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '贸易商',
  `sales_customer_id` bigint NULL DEFAULT NULL COMMENT '销售量所属客户id（用于年底返利计算）',
  `sales_customer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售量所属客户编号',
  `use_customer_level_id` bigint NULL DEFAULT NULL COMMENT '客户实际享受的等级id',
  `payment_type` int NULL DEFAULT NULL COMMENT '支付类型：1=现金支付，2=额度支付',
  `is_trader_cash_limit` tinyint(1) NULL DEFAULT 0 COMMENT '是否启用贸易商现金额度限制',
  `type` int NOT NULL DEFAULT 1 COMMENT '销售单类型：1=成品布销售，2=剪A4版',
  `cus_order_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客订订单编码',
  `cus_invoice_type` int NULL DEFAULT NULL COMMENT '客订单开票类型',
  `settlement_unit_id` int NULL DEFAULT NULL COMMENT '结算单位id',
  `inventory_organization` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '库存组织',
  `invoice_type` int NOT NULL DEFAULT 0 COMMENT '开票类型：0=不开票，1=普票，2=专票',
  `is_today_ship` tinyint NULL DEFAULT 0 COMMENT '是否今日发货',
  `await_color_transmission` tinyint NULL DEFAULT 1 COMMENT '是否需要等待对色回传中',
  `tax_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '税率',
  `current_tax_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '当前税率',
  `tax_rate_record` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '税率变更',
  `send_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送货备注',
  `picking_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '拣货备注',
  `cut_plate_outbound` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '剪板出仓:FL=丰隆剪板仓，HZ=杭州剪板仓',
  `total_goods_weight` decimal(18, 2) NULL DEFAULT NULL COMMENT '商品总重量',
  `total_goods_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '商品总金额',
  `total_goods_original_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '商品总原价（折前）',
  `total_goods_fee_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '商品费项部分金额',
  `total_goods_tax_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '商品税费部分金额',
  `total_fee_item_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '费项总金额',
  `is_use_prepayment` tinyint(1) NOT NULL DEFAULT 0 COMMENT '使用定金额度：1=是，0=否',
  `use_prepayment` decimal(18, 2) NULL DEFAULT NULL COMMENT '使用定金额度',
  `use_prepayment_rate` decimal(8, 2) NULL DEFAULT NULL COMMENT '使用定金额度比例',
  `valid_use_prepayment` decimal(18, 2) NULL DEFAULT NULL COMMENT '可用定金额度',
  `is_use_account_balance` tinyint(1) NOT NULL DEFAULT 0 COMMENT '使用账户余额：1=是，0=否',
  `use_account_balance` decimal(18, 2) NULL DEFAULT NULL COMMENT '使用账户余额',
  `valid_use_account_balance` decimal(18, 2) NULL DEFAULT NULL COMMENT '可用账户余额',
  `total_due_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '应收总金额',
  `picking_finish_time` datetime NULL DEFAULT NULL COMMENT '拣货完成时间',
  `picking_directive` int NOT NULL DEFAULT 1 COMMENT '拣货指令 1=未推送，2=已推送，3=异常',
  `shipments_directive` int NOT NULL DEFAULT 1 COMMENT '发货指令 1=未推送，2=已推送，3=异常',
  `shipments_finish_time` datetime NULL DEFAULT NULL COMMENT '发货完成时间',
  `large_goods_discount_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '大货优惠',
  `large_goods_is_use_discount` tinyint(1) NOT NULL DEFAULT 0 COMMENT '大货是否使用优惠：1=是，0=否',
  `cut_sheet_discount_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '剪板优惠',
  `valid_coupon_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '可用优惠卷金额',
  `cut_sheet_is_use_discount` tinyint(1) NOT NULL DEFAULT 0 COMMENT '剪板是否使用优惠：1=是，0=否',
  `zh_hang_tag_qty` int NULL DEFAULT NULL COMMENT '中文吊牌出仓',
  `is_zh_hang` tinyint(1) NULL DEFAULT 0 COMMENT '是否发起中文吊牌出仓',
  `en_hang_tag_qty` int NULL DEFAULT NULL COMMENT '英文吊牌出仓',
  `is_en_hang` tinyint(1) NULL DEFAULT 0 COMMENT '是否发起英文吊牌出仓',
  `total_goods_prorate_weight` decimal(10, 1) NULL DEFAULT NULL COMMENT '商品均摊总重量(业务不需要)',
  `is_merge_ship` tinyint(1) NULL DEFAULT 0 COMMENT '是否合并发货：1=是，0=否',
  `new_goods_audit` int NULL DEFAULT 1 COMMENT '新品审批状态(1=无需审批、2=审批中、3=审批通过、4=审批不通过)',
  `dye_lot_audit` int NULL DEFAULT 1 COMMENT '炒雪花指定缸号审批状态(1=无需审批、2=审批中、3=审批通过、4=审批不通过)',
  `trial_cut_audit` int NULL DEFAULT 1 COMMENT '试裁优惠审核(1=无需审批、2=审批中、3=审批通过、4=审批不通过)',
  `payment_method` int NULL DEFAULT NULL COMMENT '付款形式（1=全额付款，2=预付款+尾款组合付款）',
  `pre_payment_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '预付款金额',
  `payment_way` int NULL DEFAULT NULL COMMENT '支付方式(1=对公，2=动态码)',
  `modify_version_no` int NULL DEFAULT NULL COMMENT '修改版本号',
  `send_order_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送货单号',
  `click_snowflake` tinyint(1) NULL DEFAULT 0 COMMENT '炒雪花按钮是否点击',
  `is_full_order_exchange` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否发起整单换货(0=未发起，1=发起)',
  `exchange_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '换货销售单号',
  `exchange_customer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '换货客户编号',
  `order_node_time` datetime NULL DEFAULT NULL COMMENT '下单时间',
  `finish_node_time` datetime NULL DEFAULT NULL COMMENT '出数完成时间',
  `countdown_time` datetime NULL DEFAULT NULL COMMENT '锁缸/对色倒计时',
  `bill_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据所属员',
  `bill_position` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据所属岗位',
  `bill_department` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据所属部门',
  `position` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属岗位',
  `department` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '建单部门',
  `submitter` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=启用，0=停用',
  `use_gross_weight` int NULL DEFAULT NULL COMMENT '下单计算重量方式：1=净重下单,2=毛重下单',
  `unit` int NULL DEFAULT NULL COMMENT '下单计算单位：0=公斤,1=米',
  `deductMode` tinyint NULL DEFAULT NULL,
  `deduct_mode` tinyint NULL DEFAULT NULL COMMENT '抵扣模式：1整单抵扣，0部分抵扣',
  `product_type` int NULL DEFAULT NULL COMMENT '明细中商品类型 1=大货，2=剪板，3=大货和剪板',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unique_idx_order_no`(`order_no` ASC) USING BTREE,
  INDEX `idx_customer`(`customer_id` ASC) USING BTREE,
  INDEX `idx_customer_order`(`cus_order_code` ASC) USING BTREE,
  INDEX `idx_customer_code`(`customer_code` ASC) USING BTREE,
  INDEX `idx_customer_name`(`customer_name` ASC) USING BTREE,
  INDEX `idx_trade`(`trader_id` ASC) USING BTREE,
  INDEX `key_countdown_time`(`countdown_time` ASC) USING BTREE,
  INDEX `key_order_node_time`(`order_node_time` ASC) USING BTREE,
  INDEX `idx_sales_order_customer_status_finish`(`sales_customer_id` ASC, `delete_status` ASC, `status` ASC, `finish_node_time` ASC, `id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2104015921632632835 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售单主表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_sales_order_async
-- ----------------------------
DROP TABLE IF EXISTS `jf_sales_order_async`;
CREATE TABLE `jf_sales_order_async`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '方法名',
  `request_data` json NULL COMMENT '请求入参',
  `sales_order_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售单编码',
  `async_success` tinyint(1) NULL DEFAULT NULL COMMENT '异步状态（1：成功，0：失败）',
  `async_data` json NULL COMMENT '异步结果',
  `created_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sales_order_code`(`sales_order_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4586 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售单异步结果' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_sales_order_change_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_sales_order_change_record`;
CREATE TABLE `jf_sales_order_change_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `sales_order_id` bigint NOT NULL COMMENT '销售单ID',
  `change_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '变更类型',
  `change_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '变更明细',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=已删除，0=未删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sales_order_id`(`sales_order_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2104404837824049154 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售单变更记录' ROW_FORMAT = DYNAMIC;

