  `payment_way` int NULL DEFAULT NULL COMMENT '支付方式(1=对公，2=动态码)',
  `modify_version_no` int NULL DEFAULT NULL COMMENT '修改版本号',
  `send_order_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送货单号',
  `click_snowflake` tinyint(1) NULL DEFAULT 0 COMMENT '炒雪花按钮是否点击',
  `is_full_order_exchange` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否发起整单换货(0=未发起，1=发起)',
  `exchange_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '换货销售单号',
  `exchange_customer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '换货客户编号',
  `order_node_time` datetime NULL DEFAULT NULL COMMENT '下单时间',
  `finish_node_time` datetime NULL DEFAULT NULL COMMENT '出数完成时间',
  `countdown_time` datetime NULL DEFAULT NULL COMMENT '锁缸/对色倒计时',
  `bill_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据所属员',
  `bill_position` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据所属岗位',
  `bill_department` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据所属部门',
  `position` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属岗位',
  `department` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '建单部门',
  `submitter` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=启用，0=停用',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_customer`(`customer_id` ASC) USING BTREE,
  INDEX `idx_customer_order`(`cus_order_code` ASC) USING BTREE,
  INDEX `idx_customer_code`(`customer_code` ASC) USING BTREE,
  INDEX `idx_customer_name`(`customer_name` ASC) USING BTREE,
  INDEX `idx_trade`(`trader_id` ASC) USING BTREE,
  INDEX `key_countdown_time`(`countdown_time` ASC) USING BTREE,
  INDEX `key_order_node_time`(`order_node_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2161 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售单主表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_sales_order_cus
-- ----------------------------
DROP TABLE IF EXISTS `jf_sales_order_cus`;
CREATE TABLE `jf_sales_order_cus`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `sales_order_id` bigint NOT NULL COMMENT '销售单ID',
  `cus_id` bigint NULL DEFAULT NULL COMMENT '客户ID',
  `cus_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户编号',
  `cus_short_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户简称（往来单位）',
  `parent_cus_id` bigint NULL DEFAULT NULL COMMENT '父级客户ID',
  `parent_cus_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '父级客户编号',
  `company` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '公司全称（单位全称）',
  `control_account_period_id` bigint NULL DEFAULT NULL COMMENT '结算方式ID',
  `cus_payment` bigint NULL DEFAULT NULL COMMENT '支付方式(1:现金客户，2:额度客户)',
  `is_star_cus` tinyint(1) NULL DEFAULT 0 COMMENT '是否标星客户 (0:否, 1:是)',
  `is_over_due` tinyint(1) NULL DEFAULT 0 COMMENT '是否逾期 (0:否 1:是)',
  `is_net_weight` tinyint(1) NULL DEFAULT NULL COMMENT '是否全净重',
  `raise_sales_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '增加销售单价（元）',
  `is_merge_discounts` tinyint(1) NULL DEFAULT 0 COMMENT '是否使用了合并优惠（0:未使用，1：使用）',
  `ordering_discount_methods` int NOT NULL DEFAULT 2 COMMENT '下单优惠方式(1-先优惠；2-后优惠)',
  `customer_level_id` bigint NULL DEFAULT NULL COMMENT '客户等级id',
  `customer_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户等级',
  `customer_discount_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '等级优惠金额',
  `parent_level_id` bigint NULL DEFAULT NULL COMMENT '父级客户等级id',
  `parent_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '父级客户等级',
  `parent_discount_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '父级等级优惠金额',
  `contact_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '联系电话',
  `brand` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属品牌',
  `brand_parent` tinyint(1) NULL DEFAULT 0 COMMENT '品牌父级',
  `consignee` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收货人',
  `province` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '省',
  `city` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '市',
  `area` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区/县',
  `street` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '街道',
  `deliver_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送货备注',
  `delivery_lifter` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送货抬头',
  `final_manufacturer` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最终厂家',
  `business_group` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务组别',
  `business_manager` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务经理',
  `store_sales` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '门店销售',
  `delivery_method` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发货方式名称',
  `delivery_id` bigint NULL DEFAULT NULL COMMENT '收货信息id',
  `trader_short_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '贸易商简称',
  `trader_group` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '贸易商组别',
  `trader_id` bigint NULL DEFAULT NULL COMMENT '贸易商id',
  `is_all_votes` int NULL DEFAULT NULL COMMENT '全票（0-否；1-全票3%；2-全票6%；）',
  `delivery_method_id` bigint NULL DEFAULT NULL COMMENT '发货方式id(jf_delivery_method表)',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  `adjusted_discount_quota` decimal(10, 2) NULL DEFAULT NULL COMMENT '等级优惠金额',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sales_order`(`sales_order_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2104015921758461955 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售订单客户表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_sales_order_detail
-- ----------------------------
DROP TABLE IF EXISTS `jf_sales_order_detail`;
CREATE TABLE `jf_sales_order_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `source_id` bigint NOT NULL COMMENT '来源ID',
  `sales_order_id` bigint NOT NULL COMMENT '销售单id',
  `sales_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售单号',
  `type` int NOT NULL COMMENT '类型（1=大货，2=剪板）',
  `product_id` bigint NOT NULL COMMENT '产品颜色备案id',
  `spu` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品编码',
  `goods_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品名称',
  `spu_sales_category` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'spu销售类型',
  `goods_type` int NULL DEFAULT NULL COMMENT '商品类型 1=主身，2=罗纹',
  `color_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '色号',
  `color_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '颜色',
  `sku` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SKU',
  `is_small_strip` tinyint(1) NULL DEFAULT NULL COMMENT '优先小条：1=是，0=否',
  `quantity` decimal(12, 1) NULL DEFAULT NULL COMMENT '数量/散剪数量(米数/重量)',
  `frozen_quantity` decimal(12, 1) NULL DEFAULT NULL COMMENT '冻结条数',
  `unit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位/散剪单位',
  `sample_quantity` decimal(12, 1) NULL DEFAULT NULL COMMENT '预估数量',
  `tax_rate` decimal(8, 2) NULL DEFAULT NULL COMMENT '税率',
  `tax_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '税额',
  `sample_unit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预估数量单位',
  `base_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '标准价',
  `latest_sales_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '最新销售价',
  `net_weight_unit_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '净重单价',
  `modify_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '调整价',
  `dyeing_surcharge` decimal(12, 2) NULL DEFAULT NULL COMMENT '小缸费',
  `is_tax` tinyint(1) NULL DEFAULT NULL COMMENT '含税：1=是，0=否',
  `is_net_weight` tinyint(1) NULL DEFAULT 1 COMMENT '净重：1=是，0=否',
  `single_fabric_weight` decimal(12, 1) NULL DEFAULT 25.0 COMMENT '单疋重',
  `pre_net_weight` decimal(12, 1) NULL DEFAULT NULL COMMENT '勾选净重（重量）',
  `post_net_weight` decimal(12, 1) NULL DEFAULT NULL COMMENT '未勾选净重（重量）',
  `net_weight_coefficient` decimal(5, 2) NULL DEFAULT 1.00 COMMENT '净重系数(剪板默认为1)',
  `budget_weight` decimal(12, 1) NOT NULL COMMENT '预算重量(拣货前)',
  `actual_weight` decimal(12, 1) NULL DEFAULT NULL COMMENT '实际重量(拣货后)',
  `actual_sample_weight` decimal(12, 1) NULL DEFAULT NULL COMMENT '实际重量（对应单位sample_unit）',
  `discount_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '优惠单价',
  `discount_type` int NULL DEFAULT NULL COMMENT '优惠类型，1=等级优惠、2=等级优惠+首条优惠、3=灵活优惠、4=灵活优惠+首条优惠,5=首条优惠',
  `post_discount_unit_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '优惠后单价（不含费项目）',
  `tax_included_unit_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '含税单价',
  `tax_included_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '含税金额',
  `tax_excluded_unit_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '不含税单价',
  `tax_excluded_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '不含税金额',
  `roll_line_weight` decimal(12, 1) NULL DEFAULT NULL COMMENT '驳口优惠重量',
  `roll_line_sample_weight` decimal(12, 1) NULL DEFAULT NULL COMMENT '驳口优惠重量（对应单位sample_unit）',
  `roll_line_included_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '驳口含税优惠金额',
  `roll_line` int NULL DEFAULT NULL COMMENT '驳口数',
  `roll_line_excluded_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '驳口不含税优惠金额',
  `specify_dyeing_machine_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '指定缸号',
  `specify_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '指定原因',
  `style_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '款号',
  `color_match_sales_order_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对色销售单编码',
  `color_match_sku` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对色SKU',
  `color_match_spu` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对色商品编码',
  `color_match_goods_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对色商品名称',
  `color_match_materials` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对色资料',
  `color_match_color_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对色色号',
  `color_match_type` int NULL DEFAULT NULL COMMENT '对色商品类型（1=大货，2=剪板）',
  `pre_length` decimal(12, 2) NULL DEFAULT NULL COMMENT '洗前出米数（剪板专用）',
  `cut_meter_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '剪米价',
  `scattered_unit_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '散剪单价',
  `min_sales_price` decimal(20, 4) NULL DEFAULT NULL COMMENT '最低售价',
  `error_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '错误码(0001=库存不足，0002=需手工对色，0003-006=预警/其他异常)',
  `error_msg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '错误信息',
  `lock_dye_lot` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '锁缸结果',
  `compare_color_flag` tinyint NULL DEFAULT NULL COMMENT '对色结果标记',
  `compare_color_change` tinyint NULL DEFAULT 0 COMMENT '对色是否已变更',
  `compare_color` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对色结果',
  `now_inventory_qty` int NULL DEFAULT NULL COMMENT '当时可用条数',
  `kg_discount` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '每公斤优惠价（剪板优惠）',
  `discount_amount` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '优惠金额',
  `is_merge_discounts` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否使用了合并优惠（0:未使用，1：使用）',
  `merge_customer_id` bigint NULL DEFAULT NULL COMMENT '主身客户id',
  `customer_level_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户等级',
  `parent_customer_level_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '父级客户等级',
  `merge_parent_customer_id` bigint NULL DEFAULT NULL COMMENT '合并优惠的父级拥有者',
  `modify_version_no` int NULL DEFAULT NULL COMMENT '修改版本号',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=已删除，0=未删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sales_order`(`sales_order_id` ASC) USING BTREE,
  INDEX `idx_product`(`product_id` ASC) USING BTREE,
  INDEX `idx_sales_order_detail_order_delete`(`sales_order_id` ASC, `delete_status` ASC, `id` ASC, `type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2104015921884291076 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售单明细' ROW_FORMAT = DYNAMIC;

