-- ----------------------------
-- Table structure for jf_sales_order_discount
-- ----------------------------
DROP TABLE IF EXISTS `jf_sales_order_discount`;
CREATE TABLE `jf_sales_order_discount`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `sales_order_id` bigint NULL DEFAULT NULL COMMENT '销售单id',
  `sales_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '销售单编码',
  `discount_strategy` int NULL DEFAULT NULL COMMENT '优惠策略：1=试裁优惠、2=小条优惠、3=优惠卷优惠',
