  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售单物流进度表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_sales_order_oa_audit
-- ----------------------------
DROP TABLE IF EXISTS `jf_sales_order_oa_audit`;
CREATE TABLE `jf_sales_order_oa_audit`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
