  `approval_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批节点编码',
  `approval_status` int NULL DEFAULT NULL COMMENT '审批状态(1=无需审批,2=审批中,3=审批通过,4=审批不通过)',
  `discount_price` decimal(8, 2) NULL DEFAULT NULL COMMENT '优惠单价（灵活优惠）',
  `adjustment_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '优惠调价单号（灵活优惠）',
  `approval_finish_time` datetime NULL DEFAULT NULL COMMENT '审批完成时间',
