  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=已删除，0=未删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 277 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售单OA审批表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_sales_order_picking_detail
-- ----------------------------
DROP TABLE IF EXISTS `jf_sales_order_picking_detail`;
CREATE TABLE `jf_sales_order_picking_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `sales_order_id` bigint NOT NULL COMMENT '销售单id',
  `sales_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售单号',
  `sales_order_detatil_id` bigint NULL DEFAULT NULL COMMENT '销售单明细id',
  `type` int NOT NULL COMMENT '类型（1=大货，2=剪板）',
  `sku` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'sku',
  `dye_lot_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成品缸号',
  `fixed_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '疋号',
  `quantity` int NULL DEFAULT NULL COMMENT '条数/散剪数量',
  `unit` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位',
  `product_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '细码',
  `gross_weight` decimal(10, 1) NULL DEFAULT NULL COMMENT '毛重',
  `net_weight` decimal(10, 1) NULL DEFAULT NULL COMMENT '净重/称重重量',
  `meters` decimal(10, 2) NULL DEFAULT NULL COMMENT '米数',
  `wash_yards` decimal(10, 2) NULL DEFAULT NULL COMMENT '码数',
  `roll_line` int NULL DEFAULT NULL COMMENT '驳口数',
  `return_status` int NULL DEFAULT 0 COMMENT '退货状态: 0=未退货、1=已退货',
  `ware_house_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '逻辑仓',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=已删除，0=未删除',
  `trial_discount` tinyint(1) NOT NULL DEFAULT 0 COMMENT '试裁优惠',
  `small_discount` tinyint(1) NOT NULL DEFAULT 0 COMMENT '小条优惠',
  `cut_discount` tinyint(1) NOT NULL DEFAULT 0 COMMENT '优惠卷优惠/剪板优惠',
  `trial_discount_amount` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '试裁优惠金额',
  `small_discount_amount` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '小条优惠金额',
  `cut_discount_amount` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '优惠卷优惠/剪板优惠金额',
  `discount_strategy` int NULL DEFAULT NULL COMMENT '优惠策略：1=试裁优惠、2=小条优惠、3=优惠卷优惠',
  `discount_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '优惠金额（大货专用）(废弃字段)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sales_order`(`sales_order_id` ASC) USING BTREE,
  INDEX `idx_product`(`sku` ASC) USING BTREE,
  INDEX `idx_picking_detail_detail_delete`(`sales_order_detatil_id` ASC, `delete_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4951 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售单拣货明细' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_sales_order_quota_usage_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_sales_order_quota_usage_record`;
CREATE TABLE `jf_sales_order_quota_usage_record`  (
