  `quota_id` bigint NULL DEFAULT NULL COMMENT '额度id(jf_contract_quota_customer)',
  `assign_quota_id` bigint NULL DEFAULT NULL COMMENT '分配额度id(jf_quota_allocation_record)',
  `is_using_own` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否使用自己额度',
