  INDEX `idx_quota_id_delete_status`(`quota_id` ASC, `delete_status` ASC) USING BTREE,
  INDEX `idx_assign_quota_id_delete_status`(`assign_quota_id` ASC, `delete_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2104015923964665859 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售单额度使用记录表（记录使用自己的额度，还是分配的额度）' ROW_FORMAT = Dynamic;

