-- ----------------------------
-- Table structure for jf_sales_order_status_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_sales_order_status_record`;
CREATE TABLE `jf_sales_order_status_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `sales_order_id` bigint NULL DEFAULT NULL COMMENT '销售单ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '销售单编码',
  `sales_order_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '单据状态：1=草稿，2=OA审核通中，3=0A审核不通过，4=库存不足，5=锁缸结果待确认，6=对色结果待确认，7=已锁缸，8=已派单，9=拣货中，10=已出数，11=待发进仓，12=派车，13=待发出仓，14=付运,15=送达，16=已取消',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=已删除，0=未删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sales_order`(`sales_order_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2104017802220134403 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售单-状态变更' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_sales_order_test
-- ----------------------------
DROP TABLE IF EXISTS `jf_sales_order_test`;
CREATE TABLE `jf_sales_order_test`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '销售单编码',
  `status` int NOT NULL DEFAULT 0 COMMENT '单据状态：1=草稿，2=已提交',
  `delivery_consignee` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送货抬头',
  `customer_id` bigint NOT NULL COMMENT '客户id',
  `customer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户编号',
  `customer_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '客户名称',
  `trade_id` bigint NOT NULL COMMENT '贸易商id',
  `trade_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '贸易商',
  `customer_level_id` bigint NOT NULL COMMENT '客户等级id',
  `payment_type` int NULL DEFAULT NULL COMMENT '支付类型：1=现金支付，2=额度支付',
  `payment_way_id` bigint NULL DEFAULT NULL COMMENT '支付方式id',
  `payment_way` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '支付方式',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售单标题',
  `type` int NOT NULL DEFAULT 1 COMMENT '销售单类型：1=成品布销售，2=剪A4版',
  `customer_order_id` bigint NOT NULL COMMENT '客订订单id',
  `settlement_unit_id` int NULL DEFAULT NULL COMMENT '结算单位id',
  `inventory_organization` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '库存组织',
  `invoice_type` int NOT NULL DEFAULT 1 COMMENT '开票类型：1=不开票，2=普票，3=专票',
  `is_tax_included` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否含税：1=是，0=否',
  `order_date` date NOT NULL COMMENT '下单时间',
  `is_today_ship` tinyint NULL DEFAULT 0 COMMENT '是否今日发货',
  `tax_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '税率',
  `send_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送货备注',
  `picking_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '拣货备注',
  `cut_plate_outbound` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '剪板出仓:1=丰隆剪板仓，2=杭州剪板仓',
  `position` varchar(0) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属岗位',
  `payment_status` int NULL DEFAULT NULL COMMENT '付款状态：1=未付款, 2=部分结清, 3=已结清',
  `total_goods_weight` decimal(18, 2) NULL DEFAULT NULL COMMENT '商品总重量',
  `total_goods_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '商品总金额',
  `total_fee_item_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '费项总金额',
  `is_use_prepayment` tinyint(1) NOT NULL DEFAULT 0 COMMENT '使用定金额度：1=是，0=否',
  `use_prepayment` decimal(18, 2) NULL DEFAULT NULL COMMENT '本次销售单使用定金额度',
  `is_use_account_balance` tinyint(1) NOT NULL DEFAULT 0 COMMENT '使用账户余额：1=是，0=否',
  `use_account_balance` decimal(18, 2) NULL DEFAULT NULL COMMENT '本次销售单使用账户余额抵扣金额',
  `total_due_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '应收总金额',
  `picking_finish_time` datetime NULL DEFAULT NULL COMMENT '拣货完成时间',
  `picking_directive` int NOT NULL DEFAULT 1 COMMENT '拣货指令 1=未推送，2=已推送，3=异常',
  `shipments_directive` int NOT NULL DEFAULT 1 COMMENT '发货指令 1=未推送，2=已推送，3=异常',
  `delivery_method` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发货方式',
  `business_manager` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务经理',
  `store_sales` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '门店销售',
  `is_small_strip` tinyint(1) NOT NULL DEFAULT 0 COMMENT '优先小条：1=是，0=否',
  `large_goods_discount_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '大货优惠',
  `large_goods_is_use_discount` tinyint(1) NOT NULL DEFAULT 0 COMMENT '大货是否使用优惠：1=是，0=否',
  `cut_sheet_discount_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '剪板优惠',
  `cut_sheet_is_use_discount` tinyint(1) NOT NULL DEFAULT 0 COMMENT '剪板是否使用优惠：1=是，0=否',
  `zh_hang_tag_qty` int NULL DEFAULT NULL COMMENT '中文吊牌出仓',
  `en_hang_tag_qty` int NULL DEFAULT NULL COMMENT '英文吊牌出仓',
  `is_merge_ship` tinyint(1) NULL DEFAULT NULL COMMENT '是否合并发货：1=是，0=否',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=启用，0=停用',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售单主表' ROW_FORMAT = DYNAMIC;

