  `delivery_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送货地址',
  `delivery_lifter` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送货抬头',
  `invoice_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开票类型',
  `tax_rate` decimal(8, 2) NULL DEFAULT NULL COMMENT '税率',
  `inventory_organization` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '库存组织',
  `created_time` datetime NULL DEFAULT NULL COMMENT '销售单创建时间',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '销售单审核日期',
  `sales_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售类别',
  `bill_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据类别',
  `quantity` decimal(12, 2) NULL DEFAULT NULL COMMENT '销售条数',
  `pre_net_weight` decimal(12, 2) NULL DEFAULT NULL COMMENT '销售净重，勾选净重（重量）',
  `post_net_weight` decimal(12, 2) NULL DEFAULT NULL COMMENT '销售重量，未勾选净重（重量）',
  `bill_status` int NULL DEFAULT NULL COMMENT '单据状态',
  `pay_status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款状态',
  `total_goods_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '商品总金额',
  `tax_included_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '含税金额',
  `sales_discount_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '销售单优惠价',
  `cus_order_discount_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '客订订单优惠价',
  `fee_order_discount_price` decimal(12, 2) NULL DEFAULT NULL COMMENT '费项单优惠价',
  `tax_refund_form` decimal(12, 2) NULL DEFAULT NULL COMMENT '退税单',
  `shipments_time` datetime NULL DEFAULT NULL COMMENT '发货时间',
  `bill_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据所属员',
  `bill_position` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据所属岗位',
  `bill_department` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据所属部门',
  `position` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属岗位',
  `wide_created_time` datetime NULL DEFAULT NULL COMMENT '宽表数据创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_created_time`(`created_time` ASC) USING BTREE,
  INDEX `idx_customer_name`(`customerName` ASC) USING BTREE,
  INDEX `idx_order_no`(`order_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 40 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售订单宽表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_sales_return
-- ----------------------------
DROP TABLE IF EXISTS `jf_sales_return`;
CREATE TABLE `jf_sales_return`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `request_order_id` bigint NOT NULL DEFAULT 1 COMMENT '销售退货申请ID',
  `return_order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '销售退货单号',
  `status` int NULL DEFAULT 1 COMMENT '审批状态：1=待收货、2=待质检、3=质检完成、4=待业务确认、5=待复检,  6=回修中, 7==待出货、8=已完成、9=已关闭',
  `return_status` int NULL DEFAULT NULL COMMENT '退款状态: 1=待退款、2=已退款',
  `order_type` int NOT NULL COMMENT '单据类型: 1=拦截退, 2=退货',
  `is_split` tinyint NULL DEFAULT 0 COMMENT '是否拆单',
  `is_abnormal` tinyint NULL DEFAULT 0 COMMENT '是否异常',
  `refund_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '退款金额',
  `pending_confirm_time` datetime NULL DEFAULT NULL COMMENT '待业务确认节点时间',
  `business_confirm` tinyint NULL DEFAULT NULL COMMENT '业务确认1=接受QC结果、0=不接受QC结果',
  `business_confirm_time` datetime NULL DEFAULT NULL COMMENT '业务确认时间',
  `business_confirm_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务确认人',
  `abnormal_confirm` tinyint NULL DEFAULT NULL COMMENT '异常确认1=接受,0=不接受',
  `abnormal_confirm_time` datetime NULL DEFAULT NULL COMMENT '异常确认时间',
  `abnormal_confirm_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常确认人',
  `re_quality_time` datetime NULL DEFAULT NULL COMMENT '发起重新质检时间',
  `re_quelity_callback` tinyint NULL DEFAULT 0 COMMENT '发起重新质检48小时内是否回调',
  `notice_link_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收款通知单号',
  `complete_time` datetime NULL DEFAULT NULL COMMENT '单据已完成时间',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=已删除，0=未删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sales_return_request`(`request_order_id` ASC) USING BTREE,
  INDEX `idx_return_order_filter`(`order_type` ASC, `delete_status` ASC, `status` ASC, `complete_time` ASC, `return_order_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 632 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售退货单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_sales_return_dye_tank
-- ----------------------------
DROP TABLE IF EXISTS `jf_sales_return_dye_tank`;
CREATE TABLE `jf_sales_return_dye_tank`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `return_order_id` bigint NOT NULL COMMENT '销售退货ID',
  `return_order_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售退货单号',
