  `discount_unit_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '折扣单价，如：0',
  `adjustment_unit_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '调整单价，如：0',
  `tax_included_unit_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '含税单价，如：51.3',
  `tax_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '含税率，如：6%',
  `total_amount` decimal(14, 2) NULL DEFAULT NULL COMMENT '总金额',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=已删除，0=未删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sales_return`(`return_order_id` ASC) USING BTREE,
  INDEX `idx_large_goods_sales_picking`(`sales_product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售退货单-产品信息缸号' ROW_FORMAT = DYNAMIC;

