-- ----------------------------
-- Table structure for jf_sales_return_request
-- ----------------------------
DROP TABLE IF EXISTS `jf_sales_return_request`;
CREATE TABLE `jf_sales_return_request`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_type` int NOT NULL COMMENT '单据类型: 1=拦截退, 2=退货',
  `request_order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '退货申请单号',
  `return_order_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销售退货单号',
  `seles_order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '销售单号',
  `sales_order_id` bigint NOT NULL COMMENT '销售单ID',
  `shipment_day` int NULL DEFAULT NULL COMMENT '已出数时间与当前已间隔',
  `status` int NULL DEFAULT 1 COMMENT '状态：1=草稿，2=待OA审核，3=OA审核通过，4=OA审核不通过, 5=已取消',
  `refund_type_id` bigint NULL DEFAULT NULL COMMENT '退货类型id',
  `refund_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '退货类型',
  `application_nature_id` bigint NULL DEFAULT NULL COMMENT '申请性质id',
  `application_nature` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请性质',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原因描述',
  `trader_id` bigint NULL DEFAULT NULL COMMENT '贸易商id',
  `business_group` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务组别',
  `want_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '客户要货状态：1=是，0=否',
  `shipper` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'JF' COMMENT '货主',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `expected_refund` decimal(10, 2) NULL DEFAULT NULL COMMENT '预计退款',
  `first_print_time` datetime NULL DEFAULT NULL COMMENT '第一次打印时间',
  `first_print_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '第一次打印人',
  `warehouse` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收货仓库',
  `transfer_receiving_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '中转收货人',
  `transfer_receiving_time` datetime NULL DEFAULT NULL COMMENT '中转收货时间',
  `warehouse_receiving_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仓库收货人',
  `warehouse_receipt_time` datetime NULL DEFAULT NULL COMMENT '仓库收货时间',
  `wms_frozen_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'WMS发起冻结单号',
  `exchange_order_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '整单换货销售单号',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=已删除，0=未删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sales_order`(`sales_order_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1057 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '销售退货申请信息' ROW_FORMAT = DYNAMIC;

