  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '销售类型名称',
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '状态',
  `sort_value` bigint NOT NULL DEFAULT 50 COMMENT '排序值',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '销售类型' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_settlement_detail
-- ----------------------------
DROP TABLE IF EXISTS `jf_settlement_detail`;
CREATE TABLE `jf_settlement_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `large_or_cut_id` bigint NULL DEFAULT NULL COMMENT '大件或剪板销售明细ID',
  `sales_order_id` bigint NULL DEFAULT NULL COMMENT '销售单id',
  `rebate_id` bigint NULL DEFAULT NULL COMMENT '返利结算单id',
  `actual_rebate_amount` decimal(16, 2) NULL DEFAULT 0.00 COMMENT '实际可返利金额',
  `final_rebate_amount` decimal(16, 2) NULL DEFAULT 0.00 COMMENT '最终确认返利金额',
  `is_compute` tinyint(1) NULL DEFAULT NULL COMMENT '参与计算状态（True：参与计算，Flase：不参加计算）',
  `is_consistent` tinyint(1) NULL DEFAULT NULL COMMENT '返利金额状态（True：实际可返利=最终确认返利，Flase：实际可返利！=最终确认返利）',
  `created_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `created_time` datetime NULL DEFAULT NULL COMMENT '操作时间',
  `updated_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改人',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态（FALSE：未删除，TRUE：已删除）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order`(`sales_order_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8271 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '年底返利结算明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
