  `business_manager` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务经理',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `yarn_delivery` int NULL DEFAULT NULL COMMENT '纱线交期(旧ERP【报期最新表】中报期确认后返回)',
  `fabric_delivery` int NULL DEFAULT NULL COMMENT '坯布交期',
  `finished_product_delivery` int NULL DEFAULT NULL COMMENT '成品交期',
  `report_person` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报期人',
  `report_time` datetime NULL DEFAULT NULL COMMENT '报期时间',
  `report_past_time` datetime NULL DEFAULT NULL COMMENT '报期过期时间',
  `is_quick_repor_period` int NULL DEFAULT NULL COMMENT '快捷报期生成:1=现货备货，2=客订备货',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3387147620303844 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '备货报期单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
