  `received_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '已收款金额',
  `unreceived_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '未收款金额',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 (0:否, 1:是)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tax`(`tax_id` ASC) USING BTREE,
  INDEX `idx_fee_item`(`fee_item_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '税费单明细（作废）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_test_project
-- ----------------------------
DROP TABLE IF EXISTS `jf_test_project`;
CREATE TABLE `jf_test_project`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '名称',
