  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除',
  `project_id` int NULL DEFAULT 0 COMMENT '旧erp测试项目id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 634 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '测试项目' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_trade_records
-- ----------------------------
DROP TABLE IF EXISTS `jf_trade_records`;
CREATE TABLE `jf_trade_records`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `trade_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '银行交易编号',
  `trade_amount` decimal(10, 2) NOT NULL COMMENT '交易金额',
  `trade_status` tinyint NOT NULL COMMENT '交易状态 (1:成功, 2:失败, 3:处理中)',
  `pay_type_id` int NOT NULL COMMENT '支付类型ID',
  `trade_time` datetime NOT NULL COMMENT '交易时间',
  `fee` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '手续费',
  `receive_amount` decimal(10, 2) NOT NULL COMMENT '实际收款金额',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '备注',
  `reference_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '',
  `caseier_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT 'i',
  `mer_id` bigint NOT NULL COMMENT '商户ID',
  `mer_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '商户名称',
  `merchant_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '静态码编号',
  `notify_result` json NULL COMMENT '银行通知的json数据',
  `channel` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '渠道（ABC|BOC）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `trade_no`(`trade_no` ASC) USING BTREE,
  INDEX `key_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '银行静态码交易记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_trade_type
-- ----------------------------
DROP TABLE IF EXISTS `jf_trade_type`;
CREATE TABLE `jf_trade_type`  (
  `id` bigint NOT NULL COMMENT '主键',
