) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '贸易商属性表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jf_trader_cash_quota_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_trader_cash_quota_record`;
CREATE TABLE `jf_trader_cash_quota_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `trader_quota_id` bigint NOT NULL COMMENT '交易商额度主键',
  `trader_id` bigint NULL DEFAULT NULL COMMENT '贸易商ID',
  `change_type` tinyint NOT NULL COMMENT '变动类型：1=冻结，2=释放',
  `change_amount` decimal(18, 2) NOT NULL COMMENT '变动金额',
  `pre_used` decimal(18, 2) NULL DEFAULT NULL COMMENT '变动前已用额度',
  `post_used` decimal(18, 2) NULL DEFAULT NULL COMMENT '变动后已用额度',
  `pre_remain` decimal(18, 2) NULL DEFAULT NULL COMMENT '变动前可用额度',
  `post_remain` decimal(18, 2) NULL DEFAULT NULL COMMENT '变动后可用额度',
  `related_business_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联业务单号（销售单号）',
  `operate_people` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作人',
  `operate_time` datetime NULL DEFAULT NULL COMMENT '操作时间',
  `change_reason` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '变动原因',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_trader_quota_id`(`trader_quota_id` ASC) USING BTREE,
