-- ----------------------------
-- Table structure for jf_trader_quota
-- ----------------------------
DROP TABLE IF EXISTS `jf_trader_quota`;
CREATE TABLE `jf_trader_quota`  (
  `id` bigint NOT NULL COMMENT '主键',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新者',
  `trader_id` bigint NULL DEFAULT NULL COMMENT '贸易商id',
  `initial_credit` decimal(31, 2) NULL DEFAULT NULL COMMENT '期初授信额度',
  `total_credit` decimal(31, 2) NULL DEFAULT NULL COMMENT '授信总额度',
  `used_credit` decimal(31, 2) NULL DEFAULT NULL COMMENT '已用授信额度',
  `freeze_credit` decimal(31, 2) NULL DEFAULT NULL COMMENT '冻结授信额度',
  `remaining_available_credit` decimal(31, 2) NULL DEFAULT NULL COMMENT '剩余可用授信额度',
  `is_cash_payment_limit` tinyint(1) NULL DEFAULT NULL COMMENT '是否启用现金支付限额',
  `initial_cash_payment_limit` decimal(31, 2) NULL DEFAULT NULL COMMENT '期初现金支付限额',
  `total_cash_payment_limit` decimal(31, 2) NULL DEFAULT NULL COMMENT '现金支付总限额',
  `used_cash_payment_limit` decimal(31, 2) NULL DEFAULT NULL COMMENT '已用现金支付额度',
  `remain_cash_payment_limit` decimal(31, 2) NULL DEFAULT NULL COMMENT '剩余可用现金支付额度',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `version` int NULL DEFAULT 0 COMMENT '版本号',
  `sign_code` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '校验码',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '贸易商额度' ROW_FORMAT = Dynamic;

