  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=启用，0=停用',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_trial_cut`(`trial_cut_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '首条试裁对象关联表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_trial_cut_discount_activity
-- ----------------------------
DROP TABLE IF EXISTS `jf_trial_cut_discount_activity`;
CREATE TABLE `jf_trial_cut_discount_activity`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '编码',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '活动名称',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `activity_type` int NOT NULL DEFAULT 1 COMMENT '活动时间类型：1=长期有效，2=时间范围',
  `sales_type` int NOT NULL DEFAULT 1 COMMENT '销售类型：1=大货销售',
  `customer_scope` int NOT NULL DEFAULT 1 COMMENT '活动对象：1=全部客户，2=等级客户，3=指定客户',
  `goods_scope` int NOT NULL DEFAULT 1 COMMENT '适用商品范围：1=全部商品，2=指定商品',
  `status` int NOT NULL DEFAULT 1 COMMENT '状态：1=待开始，2=进行中，3=已结束，4=已取消',
  `discount_rate` decimal(5, 2) NOT NULL DEFAULT 0.05 COMMENT '折扣率（%）',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `delete_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除：1=启用，0=停用',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1038 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '首条试裁折扣活动配置表' ROW_FORMAT = DYNAMIC;

