  INDEX `idx_trial_cut`(`trial_cut_id` ASC) USING BTREE,
  INDEX `idx_sku`(`spu` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '首条试裁适用商品关联表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for jf_trial_cut_use_record
-- ----------------------------
DROP TABLE IF EXISTS `jf_trial_cut_use_record`;
CREATE TABLE `jf_trial_cut_use_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `sales_order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '销售单号',
  `customer_id` bigint NOT NULL COMMENT '客户id',
  `spu` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'SPU',
  `goods_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品名称',
  `color_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '色号',
  `color_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '色称',
  `sales_unit_price` decimal(18, 2) NULL DEFAULT NULL COMMENT '销售单价（元）',
  `sales_weight` decimal(18, 2) NULL DEFAULT NULL COMMENT '销售重量（kg）',
  `sales_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '销售金额（元）',
  `discount_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '折扣率（如0.08代表8%）',
  `post_discount_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '折扣后金额（元）',
  `discount_activity_id` bigint NULL DEFAULT NULL COMMENT '优惠活动ID（关联优惠活动表）',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `created_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改人',
  `updated_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
