-- ----------------------------
-- Table structure for lcap_user
-- ----------------------------
DROP TABLE IF EXISTS `lcap_user`;
CREATE TABLE `lcap_user`  (
  `id` bigint NOT NULL COMMENT '主键',
  `created_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '第三方登录方式唯一id；普通登录使用userName+source作为userId',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '普通登录密码，密码建议加密存储。第三方登录不会存储密码',
  `phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工作电话',
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '邮箱',
  `display_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '展示的名称',
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'Normal' COMMENT '状态，标识当前用户的状态是什么',
  `source` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Normal' COMMENT '当前条用户数据来自哪个用户源，如普通登录、微信登录',
  `direct_leader_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '直属主管',
  `account_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '账号ID',
  `dept_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门id',
  `position_id` bigint NULL DEFAULT NULL COMMENT '岗位id',
  `employee_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工号id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '姓名',
  `gender` tinyint(1) NULL DEFAULT NULL COMMENT '性别（1：男；0：女）',
  `picture` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '照片',
  `is_manager` tinyint(1) NULL DEFAULT NULL COMMENT '是否为部门负责人（0：否；1：是）',
  `join_date` date NULL DEFAULT NULL COMMENT '入职日期',
  `leave_date` date NULL DEFAULT NULL COMMENT '离职日期',
  `employed_status` tinyint(1) NULL DEFAULT NULL COMMENT '在职状态（0：离职；1：在职）',
  `user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '普通登录用户名，类似账号的概念（登录账号）',
  `account_status` tinyint(1) NULL DEFAULT NULL COMMENT '账号状态（0：禁用；1：正常）',
  `is_merchandiser` tinyint(1) NULL DEFAULT NULL COMMENT '是否跟单员（0：否；1：是）',
  `agency_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交接代理人id（userId）',
  `enterprise_we_chat_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '企业微信ID',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态',
  `created_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `updated_by` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改人',
  `id_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '身份证号',
  `center_id` bigint NULL DEFAULT NULL COMMENT '所属中心（贸易商）',
  `company_id` bigint NULL DEFAULT NULL COMMENT '所属公司（关联公司表）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `userIdIndex_418e6cf`(`user_id` ASC) USING BTREE COMMENT '用户ID索引'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '人员表\r\n1 实体名称不允许改动\r\n2 默认生成的字段不允许改动\r\n3 可新增自定义字段（避免设置为非空且无默认值）' ROW_FORMAT = Dynamic;

