  `is_merchandiser` tinyint(1) NULL DEFAULT NULL COMMENT '是否跟单员（0：否；1：是）',
  `agency_id` bigint NULL DEFAULT NULL COMMENT '交接代理人id',
  `enterprise_we_chat_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '企业微信ID',
  `delete_status` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态',
