  `business_team` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务组别',
  `trader_id` int NULL DEFAULT NULL COMMENT '贸易商id',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `key_user_id`(`user_id` ASC, `delete_status` ASC) USING BTREE,
  INDEX `user_name_key`(`user_name` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '制品应用的用户实体。\r\n1 实体名称不允许改动\r\n2 默认生成的字段不允许改动\r\n3 可新增自定义字段（避免设置为非空且无默认值）' ROW_FORMAT = Dynamic;

